  images: string[];
  credits: number;
  refining: boolean;
  version: number;
  gameId?: GameId;
  category?: CategoryKey;
  modId?: string;
  modName?: string;
  steps: ThinkItem[];
  files: ModFile[];
  activeFile?: string;
  startedAt: number;
  finishedAt?: number;
