"use client";

import { useEffect, useRef, useState } from "react";
import { CategoryIcon } from "@/components/cyrus/icons/CategoryIcons";
import { GameEmblem } from "@/components/cyrus/icons/GameEmblems";
import { CheckIcon, CloseIcon, PlusIcon } from "@/components/cyrus/icons/ui";
import { CATEGORIES, EMBLEMS, GAME_COLORS, MAX_GAMES, TEMPLATES, slugify } from "@/lib/cyrus/data";
import { fx } from "@/lib/cyrus/fx";
import { CORE_ID, useGames, useStore } from "@/lib/cyrus/store";
import type { CategoryKey, EmblemKey, Game, TemplateKey } from "@/lib/cyrus/types";

const DEFAULT_CATS: CategoryKey[] = ["mechanics", "items", "creatures"];

function shortName(name: string) {
  const n = name.trim();
  if (n.length <= 12) return n;
  const first = n.split(/\s+/)[0];
  return first.length <= 12 ? first : n.slice(0, 11) + "…";
}

export function AddGameDialog() {
  const open = useStore((s) => s.addGameOpen);
  const setOpen = useStore((s) => s.setAddGameOpen);
  const addGame = useStore((s) => s.addGame);
  const select = useStore((s) => s.select);
  const toast = useStore((s) => s.toast);
  const games = useGames();

  const [name, setName] = useState("");
  const [template, setTemplate] = useState<TemplateKey>("smapi");
  const [rgb, setRgb] = useState(GAME_COLORS[4].rgb);
  const [emblem, setEmblem] = useState<EmblemKey>("chip");
  const [cats, setCats] = useState<CategoryKey[]>(DEFAULT_CATS);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (!open) return;
    // Suggest a colour the web isn't already using.
    const used = new Set(games.map((g) => g.rgb));
    setRgb((GAME_COLORS.find((c) => !used.has(c.rgb)) ?? GAME_COLORS[4]).rgb);
    setName("");
    setCats(DEFAULT_CATS);
    requestAnimationFrame(() => inputRef.current?.focus());
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open]);

  if (!open) return null;

  const trimmed = name.trim();
  const duplicate = games.some((g) => g.name.toLowerCase() === trimmed.toLowerCase());
  const full = games.length >= MAX_GAMES;
  const valid = trimmed.length >= 2 && !duplicate && !full && cats.length > 0;
  const tpl = TEMPLATES.find((t) => t.key === template)!;

  const toggleCat = (key: CategoryKey) =>
    setCats((cur) => (cur.includes(key) ? cur.filter((c) => c !== key) : cur.length >= 5 ? cur : [...cur, key]));

  const create = () => {
    if (!valid) return;
    const slug = slugify(trimmed) || "game";
    const id = `custom-${slug}-${Math.random().toString(36).slice(2, 6)}`;
    const short = shortName(trimmed);
    const game: Game = {
      id,
      name: trimmed,
      short,
      toolchain: tpl.toolchain,
      language: tpl.language,
      rgb,
      emblem,
      blurb: `Your branch · modded with ${tpl.label.toLowerCase()}.`,
      aliases: [...new Set([trimmed.toLowerCase(), short.toLowerCase(), slug.replace(/-/g, " ")])],
      categories: cats,
      template,
      custom: true,
    };
    addGame(game);
    setOpen(false);
    // Let the node mount, then bloom it out of the core with a burst of packets.
    window.setTimeout(() => {
      select({ level: "game", gameId: id });
      fx.packets([CORE_ID, id], 5, { rgb, speed: 1.4, size: 1.5, gap: 0.12 });
      fx.ripple(true);
    }, 60);
    window.setTimeout(() => fx.burst(id, rgb), 900);
    toast({ tone: "success", title: `${trimmed} joined the network`, body: `${cats.length} categories · ${tpl.label}`, rgb });
  };

  return (
    <div
      className="animate-fade fixed inset-0 z-[60] flex items-start justify-center overflow-y-auto bg-[rgb(3_3_10/0.55)] px-3 py-[8cqh] backdrop-blur-[6px] cy-light:bg-[rgb(91_33_182/0.08)]"
      onPointerDown={() => setOpen(false)}
    >
      <div
        role="dialog"
        aria-label="Add a game branch"
        className="cy5-glass animate-rise hairline-top w-full max-w-[640px] overflow-hidden rounded-3xl"
        onPointerDown={(e) => e.stopPropagation()}
        onKeyDown={(e) => {
          if (e.key === "Escape") setOpen(false);
          if (e.key === "Enter" && (e.target as HTMLElement).tagName === "INPUT") create();
        }}
      >
        <div className="flex items-start gap-5 border-b border-cy-line p-6">
          {/* Live preview of the node */}
          <div className="tint relative grid h-[104px] w-[104px] shrink-0 place-items-center" style={{ ["--c" as string]: rgb }}>
            <div
              className="absolute inset-[-28px] rounded-full"
              style={{ background: `radial-gradient(circle, rgb(${rgb} / 0.28), transparent 65%)` }}
            />
            <div
              className="relative grid h-[84px] w-[84px] place-items-center rounded-full text-[38px] transition-all duration-300"
              style={{
                color: "var(--cc-ink)",
                background: `radial-gradient(circle at 50% 30%, rgb(${rgb} / 0.22), transparent 55%), radial-gradient(circle, #0d0f2a, #06071a 80%)`,
                border: `2.5px solid rgb(${rgb})`,
                boxShadow: `0 0 12px rgb(${rgb} / 0.9), 0 0 36px rgb(${rgb} / 0.4), inset 0 0 20px rgb(${rgb} / 0.35)`,
              }}
            >
              <span className="-mt-3">
                <GameEmblem emblem={emblem} />
              </span>
            </div>
            <span
              className="absolute bottom-0 max-w-[120px] truncate rounded-full px-3 py-0.5 font-cy-display text-[12px] font-semibold text-white"
              style={{ background: "rgb(6 7 20 / 0.92)", border: `1px solid rgb(${rgb} / 0.55)` }}
            >
              {trimmed ? shortName(trimmed) : "New game"}
            </span>
          </div>
          <div className="min-w-0 flex-1">
            <div className="flex items-center gap-2">
              <h2 className="font-cy-display text-[19px] font-semibold text-cy-ink">Add a game branch</h2>
              <button type="button" onClick={() => setOpen(false)} className="cy5-btn-ghost ml-auto h-8 w-8 text-cy-muted" aria-label="Close">
                <CloseIcon />
              </button>
            </div>
            <p className="mt-1 text-[12.5px] leading-relaxed text-cy-ink-2">
              It blooms out of the core with its own categories. Prompts that mention it route straight to its branch.
            </p>
            <label className="mt-3 block">
              <span className="sr-only">Game name</span>
              <input
                ref={inputRef}
                value={name}
                onChange={(e) => {
                  setName(e.target.value);
                  fx.keystroke(0.4);
                }}
                maxLength={40}
                placeholder="Game name — e.g. Elden Ring, Satisfactory, Hollow Knight"
                className="w-full rounded-xl border border-cy-line bg-[rgb(var(--glow)/0.06)] px-3.5 py-2.5 text-[14px] text-cy-ink outline-none placeholder:text-cy-faint focus:border-cy-line-2"
              />
            </label>
            {duplicate && <p className="mt-1.5 text-[11.5px] text-rose-400">That game is already in the network.</p>}
            {full && <p className="mt-1.5 text-[11.5px] text-rose-400">The web holds {MAX_GAMES} games. Remove one to add another.</p>}
          </div>
        </div>

        <div className="space-y-5 p-6">
          <section>
            <h3 className="mb-2 text-[10.5px] font-semibold uppercase tracking-[0.16em] text-cy-muted">Code template</h3>
            <div className="grid grid-cols-1 gap-2 sm:grid-cols-2">
              {TEMPLATES.map((t) => {
                const on = t.key === template;
                return (
                  <button
                    key={t.key}
                    type="button"
                    onClick={() => setTemplate(t.key)}
                    className={`flex items-start gap-2.5 rounded-xl border px-3 py-2.5 text-left transition ${
                      on ? "border-cy-accent/60 bg-[rgb(var(--glow)/0.12)]" : "border-cy-line hover:border-cy-line-2 hover:bg-[rgb(var(--glow)/0.05)]"
                    }`}
                  >
                    <span className={`mt-0.5 grid h-4 w-4 shrink-0 place-items-center rounded-full border text-[9px] ${on ? "border-cy-accent bg-cy-accent text-white" : "border-cy-line-2"}`}>
                      {on && <CheckIcon />}
                    </span>
                    <span className="min-w-0">
                      <span className="block text-[13px] font-medium text-cy-ink">{t.label}</span>
                      <span className="block text-[11.5px] leading-snug text-cy-muted">{t.hint}</span>
                    </span>
                  </button>
                );
              })}
            </div>
          </section>

          <div className="grid grid-cols-1 gap-5 sm:grid-cols-2">
            <section>
              <h3 className="mb-2 text-[10.5px] font-semibold uppercase tracking-[0.16em] text-cy-muted">Branch colour</h3>
              <div className="flex flex-wrap gap-2">
                {GAME_COLORS.map((c) => (
                  <button
                    key={c.rgb}
                    type="button"
                    onClick={() => setRgb(c.rgb)}
                    aria-label={c.name}
                    title={c.name}
                    className="grid h-8 w-8 place-items-center rounded-full transition hover:scale-110"
                    style={{
                      background: `rgb(${c.rgb})`,
                      boxShadow: c.rgb === rgb ? `0 0 0 2px var(--solid), 0 0 0 4px rgb(${c.rgb}), 0 0 16px rgb(${c.rgb} / 0.7)` : `0 0 10px rgb(${c.rgb} / 0.4)`,
                    }}
                  >
                    {c.rgb === rgb && <CheckIcon className="text-[13px] text-white drop-shadow" />}
                  </button>
                ))}
              </div>
            </section>
            <section>
              <h3 className="mb-2 text-[10.5px] font-semibold uppercase tracking-[0.16em] text-cy-muted">Emblem</h3>
              <div className="flex flex-wrap gap-2">
                {EMBLEMS.map((em) => {
                  const on = em === emblem;
                  return (
                    <button
                      key={em}
                      type="button"
                      onClick={() => setEmblem(em)}
                      aria-label={em}
                      className="tint grid h-10 w-10 place-items-center rounded-full border text-[20px] transition"
                      style={{
                        ["--c" as string]: rgb,
                        color: on ? "var(--cc-ink)" : "var(--muted)",
                        borderColor: on ? `rgb(${rgb})` : "var(--line)",
                        boxShadow: on ? `0 0 14px rgb(${rgb} / 0.5)` : undefined,
                      }}
                    >
                      <GameEmblem emblem={em} />
                    </button>
                  );
                })}
              </div>
            </section>
          </div>

          <section>
            <h3 className="mb-2 flex items-center text-[10.5px] font-semibold uppercase tracking-[0.16em] text-cy-muted">
              Categories
              <span className="ml-2 normal-case tracking-normal text-cy-faint">{cats.length}/5 — the first three get the best spots</span>
            </h3>
            <div className="flex flex-wrap gap-1.5">
              {CATEGORIES.map((c) => {
                const on = cats.includes(c.key);
                return (
                  <button
                    key={c.key}
                    type="button"
                    onClick={() => toggleCat(c.key)}
                    className="tint flex items-center gap-1.5 rounded-full border py-1 pl-1.5 pr-2.5 text-[12px] transition"
                    style={{
                      ["--c" as string]: rgb,
                      color: on ? "var(--ink)" : "var(--muted)",
                      borderColor: on ? `rgb(${rgb} / 0.7)` : "var(--line)",
                      background: on ? `rgb(${rgb} / 0.12)` : undefined,
                    }}
                  >
                    <span className="text-[14px]" style={{ color: on ? "var(--cc)" : undefined }}>
                      <CategoryIcon k={c.key} />
                    </span>
                    {c.label}
                  </button>
                );
              })}
            </div>
          </section>
        </div>

        <div className="flex items-center gap-3 border-t border-cy-line px-6 py-4">
          <span className="text-[11.5px] text-cy-faint">
            {games.length}/{MAX_GAMES} games in the web
          </span>
          <button type="button" onClick={() => setOpen(false)} className="cy5-btn-ghost ml-auto h-9 px-3.5 text-[13px]">
            Cancel
          </button>
          <button
            type="button"
            onClick={create}
            disabled={!valid}
            className="inline-flex h-9 items-center gap-1.5 rounded-xl px-4 text-[13px] font-semibold text-white transition enabled:hover:scale-[1.03] disabled:opacity-40"
            style={{ background: `linear-gradient(135deg, rgb(${rgb}), #6366f1)`, boxShadow: valid ? `0 0 20px rgb(${rgb} / 0.5)` : undefined }}
          >
            <PlusIcon /> Add branch
          </button>
        </div>
      </div>
    </div>
  );
}

// Cyrus game registry (client-safe, data only). Adding a game = adding a row here; the home
// game selector, the version picker and the copy all read from it. No official logos or art:
// each game gets a neutral two-letter text mark.
import { MB_VERSIONS, MB_DEFAULT_VERSION } from "../modbuilder/types";

export type CyrusGameStatus = "live" | "soon";

export type CyrusGame = {
  id: string;
  name: string;
