export function PreviewPanel() {
  const open = useStore((s) => s.panelOpen);
  const selection = useStore((s) => s.selection);
  const setPanelOpen = useStore((s) => s.setPanelOpen);
  if (!open) return null;
  if (selection.level !== "mod" || !selection.modId) return <OverviewPanel onClose={() => setPanelOpen(false)} />;
  return <ModPanel modId={selection.modId} onClose={() => setPanelOpen(false)} />;
}

function OverviewPanel({ onClose }: { onClose: () => void }) {
  const selection = useStore((s) => s.selection);
  const game = useGame(selection.gameId);
  const cat = selection.category ? CATEGORY_BY_KEY[selection.category] : undefined;
  const rgb = cat?.rgb ?? game?.rgb ?? "167 139 250";
  return (
    <PanelShell>
      <header className="tint hairline-top flex items-center gap-3 px-5 pb-4 pt-5" style={{ ["--c" as string]: rgb }}>
        <span
          className={`grid h-11 w-11 shrink-0 place-items-center text-[22px] ${cat ? "rotate-45 rounded-[13px]" : "rounded-full"}`}
          style={{ color: "var(--cc)", background: `rgb(${rgb} / 0.14)`, boxShadow: `inset 0 0 0 1px rgb(${rgb} / 0.45), 0 0 24px rgb(${rgb} / 0.3)` }}
        >
          {cat ? (
            <CategoryIcon k={cat.key} className="-rotate-45" />
          ) : game ? (
            <GameEmblem emblem={game.emblem} logo={game.logo} logoTone={game.logoTone} />
          ) : (
            <span className="h-4 w-4 rounded-full bg-gradient-to-br from-white via-cy-accent to-cy-cyan shadow-[0_0_16px_var(--accent)]" />
          )}
        </span>
        <div className="min-w-0 flex-1">
          <div className="text-[10.5px] font-semibold uppercase tracking-[0.18em] text-cy-muted">
            {cat ? `${game?.name} · Category` : game ? `Game · ${game.toolchain}` : "Network overview"}
          </div>
          <h2 className="truncate font-cy-display text-[19px] font-semibold text-cy-ink">{cat?.label ?? game?.name ?? "Cyrus Core"}</h2>
        </div>
        <button type="button" onClick={onClose} className="cy5-btn-ghost h-9 w-9 text-cy-muted" aria-label="Close panel">
          <CloseIcon />
        </button>
      </header>
      <BranchOverview selection={selection} />
    </PanelShell>
  );
}

function ModPanel({ modId, onClose }: { modId: string; onClose: () => void }) {
  const mod = useMod(modId);
  const { versions, active } = useModVersions(mod);
  const job = useStore((s) => s.job);
  const tab = useStore((s) => s.panelTab);
  const setTab = useStore((s) => s.setPanelTab);
  const activeFile = useStore((s) => s.activeFile);
  const setActiveFile = useStore((s) => s.setActiveFile);
  const restoreVersion = useStore((s) => s.restoreVersion);
  const select = useStore((s) => s.select);
  const [viewing, setViewing] = useState<string | null>(null);
  const [install, setInstall] = useState(false);
  const servers = useStore((s) => s.servers);
  const realBuilds = useStore((s) => s.realBuilds);
  const realFiles = useStore((s) => s.realFiles);
  const loadRealFiles = useStore((s) => s.loadRealFiles);

  useEffect(() => setViewing(null), [modId]);

  const streaming = isJobLive(job) && job!.modId === modId;
  const viewed = viewing ? versions.find((v) => v.id === viewing) : undefined;
  const shown = viewed ?? active;
  // Nxeon: a real version's code loads from the build service the first time it is shown.
  const realV = shown?.real;
  const realState = realV ? realFiles[realV.buildId] : undefined;
  useEffect(() => {
    if (!realV || streaming || !isTerminal(realV.status) || !realV.paths.length) return;
    void loadRealFiles(realV.buildId, realV.paths.map((p) => p.path));
  }, [realV, streaming, loadRealFiles]);
  const realBuild = realV ? realBuilds.find((b) => b.id === realV.buildId) : undefined;
  const builtOk = realV?.status === "succeeded";
  const files = streaming ? job!.files : (shown?.files ?? []);
  const writingPath = streaming ? job!.activeFile : undefined;
  const current = files.find((f) => f.path === activeFile) ?? files.find((f) => f.path === writingPath) ?? files[0];

  if (!mod) {
    return (
      <PanelShell>
        <div className="grid flex-1 place-items-center p-8 text-[13px] text-cy-muted">
          This mod is no longer in the network.
          <button type="button" onClick={onClose} className="cy5-btn-ghost mt-3 px-3 py-1.5">
            Close
          </button>
        </div>
      </PanelShell>
    );
  }

  const game = getGame(mod.gameId) ?? { id: mod.gameId, name: "Unknown game", short: "Game", rgb: "167 139 250" };
  const cat = CATEGORY_BY_KEY[mod.category];

  const download = () => {
    // A real plugin downloads as the built .jar; its source as the build service's zip.
    if (realV) {
      if (builtOk) window.location.href = `/api/mod-builder/builds/${realV.buildId}/jar`;
      return;
    }
    if (!files.length) return;
    downloadBlob(zipFiles(files), `${slugify(mod.name)}-${shown?.label ?? "draft"}.zip`);
  };
  const downloadSource = () => {
    if (realV) {
      if (builtOk) window.location.href = `/api/mod-builder/builds/${realV.buildId}/source-zip`;
      return;
    }
    download();
  };

  const counts: Partial<Record<PanelTab, number>> = { files: files.length, versions: versions.length };

  return (
    <PanelShell>
      <header className="tint hairline-top px-5 pt-5" style={{ ["--c" as string]: cat.rgb }}>
        <div className="flex items-start gap-3">
          <span
            className="mt-0.5 grid h-11 w-11 shrink-0 rotate-45 place-items-center rounded-[13px] text-[21px]"
            style={{ color: "var(--cc)", background: `rgb(${cat.rgb} / 0.14)`, boxShadow: `inset 0 0 0 1px rgb(${cat.rgb} / 0.45), 0 0 24px rgb(${cat.rgb} / 0.35)` }}
          >
            <CategoryIcon k={cat.key} className="-rotate-45" />
          </span>
          <div className="min-w-0 flex-1">
            <nav className="flex items-center gap-1 text-[11px] text-cy-muted">
              <button type="button" className="hover:text-cy-ink" onClick={() => select({ level: "game", gameId: game.id })}>
                {game.name}
              </button>
              <span className="text-cy-faint">›</span>
              <button type="button" className="hover:text-cy-ink" onClick={() => select({ level: "category", gameId: game.id, category: cat.key })}>
                {cat.label}
              </button>
            </nav>
            <h2 className="truncate font-cy-display text-[19px] font-semibold leading-tight text-cy-ink">{mod.name}</h2>
            <p className="mt-0.5 line-clamp-1 text-[12px] text-cy-ink-2">{mod.summary}</p>
          </div>
          <div className="flex shrink-0 items-center gap-1">
            {streaming ? (
              <span className="flex items-center gap-1.5 rounded-full bg-cy-cyan/10 px-2.5 py-1 text-[11px] font-medium text-cy-cyan">
                <span className="h-1.5 w-1.5 animate-pulse rounded-full bg-cy-cyan" />
                Forging v{job!.version}
              </span>
            ) : (
              shown && (
                <span className="rounded-full px-2.5 py-1 text-[11px] font-semibold" style={{ color: "var(--cc-ink)", background: `rgb(${cat.rgb} / 0.13)` }}>
                  {shown.label}
                </span>
              )
            )}
            {realV && builtOk && !streaming && (
              <button
                type="button"
                onClick={() => setInstall(true)}
                className="hidden h-8 items-center gap-1.5 rounded-lg px-2.5 text-[12px] font-semibold text-white transition hover:brightness-110 sm:inline-flex"
                style={{ background: "linear-gradient(135deg, #8b5cf6, #6366f1 45%, #06b6d4)", boxShadow: "0 0 18px rgb(139 92 246 / 0.45)" }}
                title="Install this version on one of your servers"
              >
                Deploy
              </button>
            )}
            <button
              type="button"
              onClick={download}
              disabled={streaming || (realV ? !builtOk : !files.length)}
              className="cy5-btn-ghost h-9 w-9 text-cy-muted disabled:opacity-40"
              aria-label={realV ? "Download .jar" : "Download zip"}
              title={realV ? (realV.jarName ? `Download ${realV.jarName}` : "Download .jar") : "Download .zip"}
            >
              <DownloadIcon />
            </button>
            <button type="button" onClick={onClose} className="cy5-btn-ghost h-9 w-9 text-cy-muted" aria-label="Close panel">
              <CloseIcon />
            </button>
          </div>
        </div>

        <div role="tablist" className="mt-4 flex gap-1">
          {TABS.map((t) => {
            const on = t.id === tab;
            return (
              <button
                key={t.id}
                role="tab"
                aria-selected={on}
                type="button"
                onClick={() => setTab(t.id)}
                className={`relative flex items-center gap-1.5 rounded-t-lg px-3 pb-2.5 pt-1.5 text-[12.5px] font-medium transition ${on ? "text-cy-ink" : "text-cy-muted hover:text-cy-ink-2"}`}
              >
                <span className={on ? "text-cy-accent" : ""}>{t.icon}</span>
                {t.label}
                {counts[t.id] !== undefined && (
                  <span className="rounded-md bg-[rgb(var(--glow)/0.1)] px-1.5 text-[10px] tabular-nums text-cy-muted">{counts[t.id]}</span>
                )}
                {on && <span className="absolute inset-x-2 bottom-0 h-[2px] rounded-full bg-gradient-to-r from-cy-accent via-cy-pink to-cy-cyan shadow-[0_0_10px_var(--accent)]" />}
              </button>
            );
          })}
        </div>
      </header>
      <div className="h-px bg-cy-line" />

      {viewed && !streaming && (
        <div className="flex items-center gap-2 border-b border-cy-line bg-[rgb(var(--glow)/0.06)] px-4 py-2 text-[12px] text-cy-ink-2">
          <HistoryIcon className="text-cy-accent" /> Viewing {viewed.label} (read-only)
          <button type="button" onClick={() => restoreVersion(mod.id, viewed.id)} className="ml-auto font-medium text-cy-accent-ink hover:underline">
            Restore
          </button>
          <button type="button" onClick={() => setViewing(null)} className="font-medium text-cy-muted hover:text-cy-ink">
            Back to current
          </button>
        </div>
      )}

      {tab === "code" && realV && !streaming && realV.status === "failed" ? (
        <div className="grid flex-1 place-items-center p-8 text-center">
          <div className="max-w-[44ch]">
            <div className="font-cy-display text-[15px] font-semibold text-cy-ink">This version didn&apos;t build</div>
            <p className="mt-1.5 text-[12.5px] leading-relaxed text-cy-ink-2">{realV.error || "The build stopped before it finished."}</p>
            <p className="mt-2 text-[11.5px] text-cy-muted">Tokens it held went back to you. Describe the change again in the prompt to try once more.</p>
          </div>
        </div>
      ) : tab === "code" &&
        (current ? (
          <>
            <FileTabs files={files} active={current.path} writing={writingPath} onPick={setActiveFile} />
            <CodeView file={current} writing={streaming && current.path === writingPath} />
          </>
        ) : (
          <div className="grid flex-1 place-items-center p-8 text-center text-[13px] text-cy-muted">
            {streaming ? (
              <span className="shimmer-text">Cyrus is planning the files…</span>
            ) : realV && (realState === "loading" || (realState === undefined && realV.paths.length > 0)) ? (
              <span className="shimmer-text">Loading the code…</span>
            ) : realState === "error" ? (
              "The builder didn't answer. Try again in a moment."
            ) : (
              "No code yet."
            )}
          </div>
        ))}
      {tab === "files" && (
        <FilesTab
          files={files}
          active={current?.path}
          writing={writingPath}
          onOpen={(p) => {
            setActiveFile(p);
            setTab("code");
          }}
          onDownload={downloadSource}
        />
      )}
      {tab === "versions" && (
        <VersionsTab
          versions={versions}
          activeId={active?.id}
          job={streaming ? job : null}
          rgb={cat.rgb}
          onRestore={(id) => {
            restoreVersion(mod.id, id);
            setViewing(null);
          }}
          onView={(id) => {
            setViewing(id === active?.id ? null : id);
            setTab("code");
          }}
        />
      )}
      {tab === "notes" && <NotesTab mod={mod} version={shown} />}
      {install && realBuild && <InstallModal build={realBuild} servers={servers} onClose={() => setInstall(false)} onDone={() => void useStore.getState().refreshReal()} />}
    </PanelShell>
  );
}
import type { ModBuildView } from "../modbuilder/types";

export type ModelId = "katara" | "saka" | "yakko";

export type CategoryKey =
  | "weapons"
  | "creatures"
  | "worlds"
  | "mechanics"
  | "shaders"
  | "magic"
  | "quests"
  | "interface"
  | "audio"
  | "vehicles"
  | "items"
  | "characters";

/** Built-in ids are "minecraft", "palworld", "rust", "valheim", "zomboid", "terraria"; user-added games get "custom-…" ids. */
export type GameId = string;

/** Which code generator a game's mods are written with. */
export type TemplateKey = "fabric" | "papyrus" | "smapi" | "tmodloader" | "cet" | "oxide" | "bepinex" | "zomboid" | "ue4ss";

export type EmblemKey = "cube" | "dragon" | "sprout" | "tree" | "chip";

export interface Game {
  id: GameId;
  name: string;
  /** Short label used where space is tight. */
  short: string;
  /** Mod toolchain, e.g. "Fabric · Java 21". */
  toolchain: string;
  language: CodeLanguage;
  /** Neon accent used for the branch, as an "r g b" triple. */
  rgb: string;
  emblem: EmblemKey;
  /** The game's real logo (a file under /public), shown instead of the emblem where present. */
  logo?: string;
  /** "light" for white artwork, which gets inked dark on the light theme. */
  logoTone?: "light";
  blurb: string;
  aliases: string[];
  categories: CategoryKey[];
  template: TemplateKey;
  /** Added by the user from the "Add game" dialog. */
  custom?: boolean;
  /** Nxeon: Cyrus really builds for this game (the build service compiles it). The others are
   *  template previews until a real builder exists. */
  real?: boolean;
}

export interface CategoryMeta {
  key: CategoryKey;
  label: string;
  rgb: string;
  description: string;
  keywords: string[];
}

export type CodeLanguage = "java" | "papyrus" | "csharp" | "lua" | "glsl" | "json" | "markdown" | "xml" | "toml" | "text";

export interface ModFile {
  path: string;
  language: CodeLanguage;
  content: string;
}

export interface ModVersion {
  id: string;
  label: string;
  createdAt: number;
  model: ModelId;
  credits: number;
  prompt: string;
  summary: string;
  files: ModFile[];
  additions: number;
  deletions: number;
  /** Nxeon: the real build behind this version (files load from the build service on demand). */
  real?: RealVersion;
}

export interface RealVersion {
  buildId: string;
  status: string;
  mcVersion: string;
  jarName: string | null;
  jarSize: number | null;
  error: string | null;
  attempts: number;
  durationMs: number | null;
  /** Source files the build produced (paths + sizes); contents are fetched lazily. */
  paths: { path: string; size: number }[];
}

export interface Mod {
  id: string;
  gameId: GameId;
  category: CategoryKey;
  name: string;
  summary: string;
  createdAt: number;
  tags: string[];
  /** Seed mods have their files built lazily from the engine templates. */
  seed?: boolean;
  versions: ModVersion[];
  activeVersionId?: string;
  /** Nxeon: a starter idea on a real game's branch. Clicking it writes the prompt, nothing is built yet. */
  idea?: boolean;
  ideaPrompt?: string;
  /** Nxeon: a real project (ModBuild rows grouped by root). */
  real?: { rootId: string; running: boolean; failed: boolean; headBuildId: string | null; favourite: boolean };
}

export interface ModelMeta {
  id: ModelId;
  name: string;
  credits: number;
  tagline: string;
  description: string;
  rgb: string;
  /** Visual pacing for the simulated stream. */
  chunk: [number, number];
  tick: number;
}

export type Level = "core" | "game" | "category" | "mod";

export interface Selection {
  level: Level;
  gameId?: GameId;
  category?: CategoryKey;
  modId?: string;
}

/** Events streamed from /api/cyrus/generate as NDJSON lines. Nxeon adds `build` (the real build
 *  behind a Minecraft forge), `file-set` (replace a file's content: the builder edited it in
 *  place) and `ping` (keep-alive while the compiler runs). Clients ignore types they don't know. */
export type GenEvent =
  | { type: "start"; jobId: string; model: ModelId; credits: number; real?: boolean }
  | { type: "build"; build: ModBuildView }
  | { type: "file-set"; path: string; content: string }
  | { type: "ping" }
  | { type: "route"; gameId: GameId; category: CategoryKey; modName: string; modId: string; summary: string; tags: string[] }
  | { type: "think"; id: string; label: string; detail?: string }
  | { type: "think-done"; id: string }
  | { type: "file"; path: string; language: CodeLanguage }
  | { type: "chunk"; path: string; text: string }
  | { type: "file-done"; path: string }
  | { type: "done"; summary: string; notes: string; tokens?: number }
  | { type: "error"; message: string };

"use client";

// "Explain this mod": everything the build reported, in plain English, set as a
// readable document (type and hairlines, not boxes). Also the request and the images
// Cyrus looked at, and the failure explanation with retry.
import { useState } from "react";
import { isTerminal, type ModBuildView } from "@/lib/modbuilder/types";
import { cyrusModel } from "@/lib/cyrus/models";
import { viewMeta } from "@/lib/cyrus/projects";
import { estimate } from "@/lib/cyrus/estimate";
import { CyIcon, CyrusBadge, ModelMark } from "./icons";

export function Explain({ b }: { b: ModBuildView }) {
  const r = b.result;
  const s = r?.summary;
  if (b.status !== "succeeded") return <div className="cy-doc">{b.status === "failed" && <FailureDetails b={b} />}<Request b={b} lead={b.status !== "failed"} /></div>;
  return (
    <div className="cy-doc">
      <section className="cy-doc-hero">
        <span className="cy-k"><CyIcon name="explain" size={12} /> In plain English</span>
        <h3>{s?.tagline || `${b.pluginName} is built`}</h3>
        {s?.text && <p className="cy-lead">{s.text}</p>}
        {s?.changes && b.changeRequest && <p className="cy-changed"><b>What changed.</b> {s.changes}</p>}
      </section>

      {!!s?.howToUse?.length && (
        <section className="cy-doc-s">
          <h4>How to use it</h4>
          <ol className="cy-steps">{s.howToUse.map((h, i) => <li key={i}><span className="cy-step-n">{i + 1}</span><span>{h}</span></li>)}</ol>
        </section>
      )}

      {!!r?.commands?.length && (
        <section className="cy-doc-s">
          <h4>Commands <span className="cy-count">{r.commands.length}</span></h4>
          <div className="cy-rows">
            {r.commands.map((c, i) => (
              <div key={i} className="cy-row">
                <code className="cy-cmd">{c.usage}</code>
                <span className="cy-row-v">{c.description}</span>
                <span className={`cy-who ${/every/i.test(c.whoCanUse) || (!c.whoCanUse && !c.permission) ? "all" : ""}`}>{c.whoCanUse || (c.permission ? "With permission" : "Everyone")}</span>
              </div>
            ))}
          </div>
        </section>
      )}

      {!!r?.config?.length && (
        <section className="cy-doc-s">
          <h4>Settings you can change</h4>
          <p className="cy-sub">In <code className="cy-cmd">plugins/{b.pluginName}/config.yml</code> on your server.</p>
          <div className="cy-rows">
            {r.config.map((c, i) => (
              <div key={i} className="cy-row">
                <b className="cy-anywhere cy-row-k">{c.key}</b>
                <span className="cy-row-v">{c.description}</span>
                <span className="cy-row-d cy-anywhere">{c.default ? `Default ${c.default}` : ""}</span>
              </div>
            ))}
          </div>
        </section>
      )}

      {!!r?.permissions?.length && (
        <section className="cy-doc-s">
          <h4>Who can do what</h4>
          <p className="cy-sub">Works with LuckPerms or any permissions plugin.</p>
          <div className="cy-rows">
            {r.permissions.map((p, i) => (
              <div key={i} className="cy-row">
                <b className="cy-anywhere cy-row-k">{p.node}</b>
                <span className="cy-row-v">{p.description}</span>
                <span className={`cy-who ${p.default === "true" ? "all" : ""}`}>{p.default === "true" ? "Everyone" : p.default === "false" ? "Nobody by default" : "Operators"}</span>
              </div>
            ))}
          </div>
        </section>
      )}

      <Safety b={b} />

      {(!!s?.limitations?.length || !!r?.warnings?.length) && (
        <section className="cy-doc-s">
          <h4>Good to know</h4>
          <ul className="cy-bullets">
            {(s?.limitations ?? []).map((l, i) => <li key={`l${i}`}>{l}</li>)}
            {(r?.warnings ?? []).slice(0, 6).map((w, i) => <li key={`w${i}`}>{w}</li>)}
          </ul>
        </section>
      )}

      <Request b={b} />

      <section className="cy-doc-s cy-soon">
        <CyrusBadge version={b.version ? `v${b.version}` : null} />
        <p className="cy-sub">Coming to Cyrus mods: your server&apos;s Mods tab with an on/off switch, a Cyrus Mods community in NxLabs, and open source so anyone can learn from them.</p>
      </section>
    </div>
  );
}

export function Request({ b, lead }: { b: ModBuildView; lead?: boolean }) {
  const meta = viewMeta(b);
  const atts = meta.attachments ?? [];
  const m = cyrusModel(meta.model);
  const running = !isTerminal(b.status);
  const e = running ? estimate(b.changeRequest || b.prompt, m.id, { change: !!b.changeRequest }) : null;
  return (
    <section className={`cy-doc-s ${lead ? "lead" : ""}`}>
      <h4>{b.changeRequest ? "The change you asked for" : "What you asked for"}</h4>
      <blockquote className="cy-quote">{b.changeRequest || b.prompt}</blockquote>
      {b.changeRequest && <details className="cy-details"><summary>Original description</summary><p>{b.prompt}</p></details>}
      {atts.length > 0 && (
        <div className="cy-refs">
          {atts.map((a) => (
            <a key={a.n} href={`/api/mod-builder/builds/${b.id}/attachments/${a.n}`} target="_blank" rel="noreferrer" className="cy-ref" title={a.name}>
              {/* eslint-disable-next-line @next/next/no-img-element */}
              <img src={`/api/mod-builder/builds/${b.id}/attachments/${a.n}`} alt={a.name} loading="lazy" />
            </a>
          ))}
          <span className="cy-sub"><CyIcon name="eye" size={12} /> {atts.length === 1 ? "Cyrus looked at this image" : `Cyrus looked at these ${atts.length} images`} while planning.</span>
        </div>
      )}
      {lead && (
        <p className="cy-fine">
          <ModelMark tier={m.spend} /> {m.name} · Paper {b.mcVersion}
          {e && <> · usually ~{e.minutes[0]}–{e.minutes[1]} min</>}
        </p>
      )}
    </section>
  );
}

function Safety({ b }: { b: ModBuildView }) {
  const sf = b.result?.safety;
  const warns = (sf?.findings ?? []).filter((f) => f.severity === "warn");
  const checks: [string, string][] = [
    ["No internet access", "It can't send your data anywhere."],
    ["Can't run programs", "Nothing outside the game gets started."],
    ["Only its own folder", `Reads and writes only plugins/${b.pluginName || ""}.`],
    ["No hidden admin access", "No secret players with special powers."],
  ];
  return (
    <section className="cy-doc-s cy-safety">
      <h4><span className="cy-shield"><CyIcon name="shield" size={14} /></span> Safety check <span className={`cy-pill ${warns.length ? "warn" : "ok"}`}><i />{warns.length ? "Passed with notes" : "Passed"}</span></h4>
      <ul className="cy-checks">
        {checks.map(([t, d]) => <li key={t}><CyIcon name="check" size={13} strokeWidth={2.2} /><span><b>{t}</b> {d}</span></li>)}
      </ul>
      {warns.length > 0 && <p className="cy-note">This mod {Array.from(new Set(warns.map((w) => w.message))).join("; ")}. That&apos;s allowed, just worth knowing.</p>}
      <p className="cy-fine">An automated scan of the compiled code. It checks for risky behaviour; it doesn&apos;t promise the mod is bug-free.</p>
    </section>
  );
}

const FAIL: Record<string, { title: string; tips: string[] }> = {
  compile: { title: "The code didn't compile, even after fixes", tips: ["Ask for fewer features at once. You can add more as changes afterwards.", "Avoid asking for other plugins (like Vault or WorldEdit). Cyrus builds on plain Paper."] },
  safety: { title: "Blocked by the safety check", tips: ["Remove anything that needs the internet, other programs or files outside the server.", "Webhooks, Discord bots and remote databases can't be built yet."] },
  refused: { title: "Cyrus won't build this one", tips: ["Cyrus only builds mods that are safe for your players and your server."] },
  budget: { title: "This mod is bigger than one build", tips: ["Split the idea into two or three smaller mods, or try Yakko for big systems."] },
  timeout: { title: "This build ran out of time", tips: ["Split the idea into two or three smaller mods."] },
  cancelled: { title: "You stopped this build", tips: ["Start it again whenever you like."] },
  ai_unavailable: { title: "Cyrus had a hiccup", tips: ["Trying again in a minute usually works."] },
  unavailable: { title: "The builder is offline", tips: ["Try again in a few minutes."] },
  interrupted: { title: "The builder restarted mid-build", tips: ["Nothing is lost. Start it again."] },
};

const failInfo = (b: ModBuildView) => FAIL[b.errorCode || ""] ?? { title: "This one didn't build", tips: ["Try again, or describe it a little differently."] };

/** Failure details, at the top of the inspector's Request tab. */
export function FailureDetails({ b }: { b: ModBuildView }) {
  const f = failInfo(b);
  return (
    <section className="cy-doc-s lead cy-faild">
      <span className="cy-fail-k"><CyIcon name={b.errorCode === "cancelled" ? "stop" : "warn"} size={13} /> {b.errorCode === "cancelled" ? "Stopped" : "Why it didn't build"}</span>
      {b.error && <p className="cy-lead">{b.error}</p>}
      <ul className="cy-bullets">{f.tips.map((t) => <li key={t}>{t}</li>)}</ul>
      {b.result?.errorDetail && b.errorCode === "compile" && (
        <details className="cy-details"><summary>What the compiler said</summary><pre className="cy-pre">{b.result.errorDetail}</pre></details>
      )}
    </section>
  );
}

/** Failure, shown under the core on the web: the verdict and the two ways forward. */
export function Failure({ b, onRetry, onEdit }: { b: ModBuildView; onRetry: () => Promise<string | null>; onEdit: () => void }) {
  const f = failInfo(b);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);
  return (
    <div className={`cy-fail code-${b.errorCode}`}>
      <span className="cy-fail-k"><CyIcon name={b.errorCode === "cancelled" ? "stop" : "warn"} size={13} /> {b.errorCode === "cancelled" ? "Stopped" : "Didn't build"}</span>
      <h2 className="cy-fail-t">{f.title}</h2>
      {err && <p className="cy-err" role="alert">{err}</p>}
      <div className="cy-fail-act">
        {b.errorCode !== "refused" && (
          <button type="button" className="cy-btn primary" disabled={busy} onClick={async () => { setBusy(true); setErr(await onRetry()); setBusy(false); }}>
            {busy ? <i className="cy-spin" /> : <CyIcon name="retry" size={14} />} Try again
          </button>
        )}
        <button type="button" className="cy-btn" onClick={onEdit}><CyIcon name="pencil" size={14} /> {b.errorCode === "refused" ? "Describe something else" : "Edit and retry"}</button>
      </div>
    </div>
  );
}
