/**
 * Mount ONCE inside Cyrus (CyrusApp). Owns the tokens modal and the post-checkout notice;
 * chips, estimates and locks only talk to the store.
 */
export function CyrusTokensHost() {
  const snap = useCyrusTokens();
  // Back from Stripe: /dashboard/cyrus?tokens=ok|pending. Read in an effect (no hydration
  // mismatch), refresh a few times while the webhook lands, then drop the param.
  useEffect(() => {
    const u = new URL(window.location.href);
    const t = u.searchParams.get("tokens");
    if (!t) return;
    cyrusTokens.notify(t === "ok" ? "Payment received. Your tokens are in." : "Payment received. Your tokens will appear in a moment.");
    const ids = [0, 2500, 7000].map((ms) => window.setTimeout(() => void cyrusTokens.refresh(), ms));
    u.searchParams.delete("tokens");
    window.history.replaceState(null, "", u.pathname + (u.search ? u.search : "") + u.hash);
    const off = window.setTimeout(() => cyrusTokens.notify(null), 8000);
    return () => { ids.forEach(clearTimeout); clearTimeout(off); };
  }, []);
  const [host, setHost] = useState<HTMLElement | null>(null);
  useEffect(() => setHost(document.body), []);
  if (!host) return null;
  return createPortal(
    <>
      {snap.notice && (
        <div className="cy-tokens cyt-notice" role="status">
          <TokenGlyph size={16} /><span>{snap.notice}</span>
          <button type="button" aria-label="Dismiss" onClick={() => cyrusTokens.notify(null)}>×</button>
        </div>
      )}
      {snap.open && snap.state?.active && <TokensModal state={snap.state} tab={snap.tab} reason={snap.reason} />}
    </>,
    host,
  );
}

