interface Attachment {
  id: string;
  url: string;
  name: string;
  /** Nxeon: the image uploaded for real builds (/api/mod-builder/uploads); Cyrus looks at it while it plans. */
  uploadId?: string;
  state: "up" | "ok" | "err";
}

/** Upload a reference image so a real build can read it (same endpoint and limits as v4). */
async function uploadImage(f: File): Promise<string | null> {
  if (!/^image\/(png|jpe?g|webp|gif)$/.test(f.type) || f.size > 5 * 1024 * 1024) return null;
  const fd = new FormData();
  fd.append("file", f, f.name || "pasted.png");
  const r = await fetch("/api/mod-builder/uploads", { method: "POST", body: fd }).catch(() => null);
  const j = r?.ok ? ((await r.json().catch(() => null)) as { upload?: { id: string } } | null) : null;
  return j?.upload?.id ?? null;
}

export function PromptDock() {
  const [text, setText] = useState("");
  const [images, setImages] = useState<Attachment[]>([]);
  const [focused, setFocused] = useState(false);
  const [typing, setTyping] = useState(false);
  const [dragOver, setDragOver] = useState(false);
  const taRef = useRef<HTMLTextAreaElement>(null);
  const fileRef = useRef<HTMLInputElement>(null);
  const typingTimer = useRef(0);
  const typeInTimer = useRef(0);
  const voiceBase = useRef("");

  const job = useStore((s) => s.job);
  const live = isJobLive(job);
  const selection = useStore((s) => s.selection);
  const model = MODEL_BY_ID[useStore((s) => s.model)];
  const customGames = useStore((s) => s.customGames);
  const mcVersion = useStore((s) => s.mcVersion);
  const setMcVersion = useStore((s) => s.setMcVersion);
  const prefill = useStore((s) => s.prefill);
  const select = useStore((s) => s.select);
  const promptFocusTick = useStore((s) => s.promptFocusTick);
  const panelOpen = useStore((s) => s.panelOpen);
  const mod = useMod(selection.level === "mod" ? selection.modId : undefined);
  const { versions } = useModVersions(mod);

  useEffect(() => {
    if (promptFocusTick) taRef.current?.focus();
  }, [promptFocusTick]);

  // Auto-grow the textarea.
  useLayoutEffect(() => {
    const ta = taRef.current;
    if (!ta) return;
    ta.style.height = "0px";
    ta.style.height = `${Math.min(ta.scrollHeight, 180)}px`;
  }, [text]);

  const pulseTyping = useCallback(() => {
    setTyping(true);
    window.clearTimeout(typingTimer.current);
    typingTimer.current = window.setTimeout(() => setTyping(false), 1100);
  }, []);

  const addFiles = useCallback((files: File[]) => {
    const imgs = files.filter((f) => f.type.startsWith("image/")).slice(0, 4);
    if (!imgs.length) return;
    const added = imgs.map((f) => ({ f, a: { id: Math.random().toString(36).slice(2), url: URL.createObjectURL(f), name: f.name || "pasted image", state: "up" as const } }));
    setImages((prev) => [...prev, ...added.map((x) => x.a)].slice(0, 4));
    for (const { f, a } of added) {
      void uploadImage(f).then((uploadId) =>
        setImages((cur) => cur.map((i) => (i.id === a.id ? { ...i, uploadId: uploadId ?? undefined, state: uploadId ? "ok" : "err" } : i))),
      );
    }
    fx.keystroke(1.5);
  }, []);

  const onPaste = (e: ClipboardEvent<HTMLTextAreaElement>) => {
    const files = Array.from(e.clipboardData.items)
      .filter((i) => i.kind === "file" && i.type.startsWith("image/"))
      .map((i) => i.getAsFile())
      .filter((f): f is File => !!f);
    if (files.length) {
      e.preventDefault();
      addFiles(files);
    }
  };

  const onDrop = (e: DragEvent) => {
    e.preventDefault();
    setDragOver(false);
    addFiles(Array.from(e.dataTransfer.files));
  };

  const removeImage = (id: string) =>
    setImages((prev) => {
      const hit = prev.find((i) => i.id === id);
      if (hit) URL.revokeObjectURL(hit.url);
      return prev.filter((i) => i.id !== id);
    });

  const submit = () => {
    if (live || !text.trim()) return;
    window.clearInterval(typeInTimer.current);
    forge(text, images.map((i) => ({ url: i.url, uploadId: i.uploadId })));
    setText("");
    setImages([]);
  };

  // Starter ideas type themselves in — which also charges the core.
  const pickIdea = (idea: StarterIdea) => {
    if (live) return;
    window.clearInterval(typeInTimer.current);
    select({ level: "category", gameId: idea.gameId, category: idea.category });
    let i = 0;
    setText("");
    typeInTimer.current = window.setInterval(() => {
      i = Math.min(idea.prompt.length, i + 2 + Math.floor(Math.random() * 2));
      setText(idea.prompt.slice(0, i));
      fx.keystroke(0.3);
      pulseTyping();
      if (i >= idea.prompt.length) {
        window.clearInterval(typeInTimer.current);
        taRef.current?.focus();
      }
    }, 22);
  };

  useEffect(() => () => window.clearInterval(typeInTimer.current), []);

  // An idea pill on a real game's branch writes its prompt here (store.pickIdea), typed in like a starter idea.
  useEffect(() => {
    if (!prefill || live) return;
    window.clearInterval(typeInTimer.current);
    let i = 0;
    setText("");
    typeInTimer.current = window.setInterval(() => {
      i = Math.min(prefill.text.length, i + 3 + Math.floor(Math.random() * 2));
      setText(prefill.text.slice(0, i));
      fx.keystroke(0.3);
      pulseTyping();
      if (i >= prefill.text.length) {
        window.clearInterval(typeInTimer.current);
        taRef.current?.focus();
      }
    }, 18);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [prefill?.tick]);

  // Context: where in the network this prompt will land.
  const game = useGame(selection.gameId);
  const cat = selection.category ? CATEGORY_BY_KEY[selection.category] : undefined;
  const placeholder =
    selection.level === "mod" && mod
      ? `Refine ${mod.name} — e.g. "add a charged special attack"`
      : cat && game
        ? `Describe a ${game.short} ${cat.label.toLowerCase().replace(/s$/, "")} mod…`
        : game
          ? `Describe a ${game.name} mod…`
          : "Describe a mod — Cyrus routes it to the right game and category…";

  // Nxeon: will this forge be a REAL build (Minecraft: tokens, a real plugin) or a template preview?
  const realTarget = (() => {
    if (selection.level === "mod" && mod) return !!mod.real || !!mod.idea || !!game?.real;
    const t = text.trim();
    if (!t) return !!game?.real || selection.level === "core";
    const r = routePrompt(t, { gameId: selection.gameId, category: selection.category }, [...GAMES, ...customGames]);
    return !!GAMES.find((g) => g.id === r.gameId)?.real;
  })();
  const uploading = images.some((i) => i.state === "up");
  const sendable = !!text.trim() && !live && !uploading;
  const wide = useMediaQuery("(min-width: 1024px)");
  const dockStyle =
    panelOpen && wide
      ? // Nxeon: the studio is narrower than a full window (portal rail), so the dock also
        // shrinks to the space left of the panel instead of sliding under it.
        { left: "calc((100cqw - min(560px, 40cqw)) / 2)", width: "min(780px, calc(100cqw - min(560px, 40cqw) - 32px))" }
      : undefined;

  return (
    <div
      className="fixed bottom-4 left-1/2 z-30 w-[min(780px,calc(100cqw-24px))] -translate-x-1/2 transition-[left] duration-500 ease-[var(--ease-out-expo)] md:bottom-6"
      style={dockStyle}
    >
      <ThinkingTrace />

      <div
        className="prompt-shell"
        data-active={focused || typing ? "true" : "false"}
        data-busy={live ? "true" : "false"}
        onDragOver={(e) => {
          if (Array.from(e.dataTransfer.types).includes("Files")) {
            e.preventDefault();
            setDragOver(true);
          }
        }}
        onDragLeave={() => setDragOver(false)}
        onDrop={onDrop}
      >
        <div className="cy5-glass relative rounded-[24px] !border-transparent">
          {dragOver && (
            <div className="absolute inset-1.5 z-10 grid place-items-center rounded-[20px] border border-dashed border-cy-accent/60 bg-[rgb(var(--glow)/0.1)] text-[13px] font-medium text-cy-accent-ink backdrop-blur-sm">
              Drop images to give Cyrus a reference
            </div>
          )}

          {/* Context chip */}
          <div className="flex items-center gap-2 px-4 pt-3">
            {selection.level === "core" ? (
              <span className="inline-flex items-center gap-1.5 rounded-full bg-[rgb(var(--glow)/0.1)] px-2.5 py-1 text-[11px] font-medium text-cy-accent-ink">
                <SparkleIcon /> Auto-route through the core
              </span>
            ) : (
              <span
                className="tint inline-flex max-w-full items-center gap-1.5 truncate rounded-full py-1 pl-1.5 pr-1 text-[11px] font-medium text-cy-ink-2"
                style={{ ["--c" as string]: (cat ?? game)!.rgb, background: `rgb(${(cat ?? game)!.rgb} / 0.12)` }}
              >
                <span className="text-[13px]" style={{ color: "var(--cc)" }}>
                  {cat ? <CategoryIcon k={cat.key} /> : game && <GameEmblem emblem={game.emblem} logo={game.logo} logoTone={game.logoTone} />}
                </span>
                {selection.level === "mod" && mod ? (
                  <span className="truncate">
                    Refining <b className="font-semibold text-cy-ink">{mod.name}</b> → v{versions.length + 1}
                  </span>
                ) : (
                  <span className="truncate">
                    {game?.short}
                    {cat && <> › {cat.label}</>}
                  </span>
                )}
                <button
                  type="button"
                  aria-label="Clear context"
                  onClick={() => select({ level: "core" })}
                  className="ml-0.5 grid h-4 w-4 place-items-center rounded-full text-[9px] text-cy-muted hover:bg-[rgb(var(--glow)/0.15)] hover:text-cy-ink"
                >
                  <CloseIcon />
                </button>
              </span>
            )}
          </div>

          {/* Pasted images */}
          {images.length > 0 && (
            <div className="flex gap-2 overflow-x-auto px-4 pt-2.5">
              {images.map((img) => (
                <div key={img.id} className="animate-pop group relative h-16 w-16 shrink-0 overflow-hidden rounded-xl border border-cy-line-2">
                  {/* eslint-disable-next-line @next/next/no-img-element */}
                  <img src={img.url} alt={img.name} className="h-full w-full object-cover" />
                  <div className="absolute inset-0 bg-gradient-to-t from-black/40 to-transparent" />
                  {img.state !== "ok" && (
                    <span className="absolute inset-x-0 bottom-0 bg-black/55 py-0.5 text-center text-[9px] font-medium text-white" title={img.state === "err" ? "Couldn't upload: Cyrus won't see this image" : undefined}>
                      {img.state === "up" ? "Uploading…" : "Not sent"}
                    </span>
                  )}
                  <button
                    type="button"
                    aria-label={`Remove ${img.name}`}
                    onClick={() => removeImage(img.id)}
                    className="absolute right-1 top-1 grid h-5 w-5 place-items-center rounded-full bg-black/60 text-[10px] text-white opacity-0 transition group-hover:opacity-100"
                  >
                    <CloseIcon />
                  </button>
                </div>
              ))}
            </div>
          )}

          <textarea
            ref={taRef}
            rows={1}
            value={text}
            disabled={live}
            placeholder={live ? "Cyrus is forging… you can watch the beams travel the branch." : placeholder}
            onChange={(e) => {
              setText(e.target.value);
              fx.keystroke();
              pulseTyping();
            }}
            onKeyDown={(e) => {
              if (e.key === "Enter" && !e.shiftKey && !e.nativeEvent.isComposing) {
                e.preventDefault();
                submit();
              }
            }}
            onPaste={onPaste}
            onFocus={() => setFocused(true)}
            onBlur={() => setFocused(false)}
            className="prompt-textarea block max-h-[180px] w-full resize-none bg-transparent px-4 pb-2 pt-2.5 text-[15px] leading-relaxed text-cy-ink outline-none disabled:opacity-60"
            aria-label="Describe your mod"
          />

          {/* Toolbar */}
          <div className="flex items-center gap-1.5 px-2.5 pb-2.5">
            <ModelSelect disabled={live} />
            <input
              ref={fileRef}
