<path d="${MARK_SWEEP}" fill="url(#${id}-ss)"/>
<path d="M323 412.6 L593.5 182.6" stroke="url(#${id}-sh)" stroke-width="6" stroke-linecap="round"/>
<path d="${MARK_SWEEP}" fill="none" stroke="#2a1580" stroke-opacity="0.35" stroke-width="1.6"/>
<path d="${MARK_ARM}" fill="url(#${id}-af)"/>
<path d="${MARK_ARM}" fill="url(#${id}-as)"/>
