import { MARK_ASPECT, MARK_VIEWBOX, markInner } from "./cyrusMark";

/** The Cyrus "Y" mark. Height follows `1em`. Rendered from the same markup the 3D core uses. */
export function CyrusGlyph({ id = "cyrus-mark", ...props }: { id?: string } & SVGProps<SVGSVGElement>) {
  return (
    <svg
      viewBox={MARK_VIEWBOX}
      width={`${MARK_ASPECT.toFixed(3)}em`}
      height="1em"
      role="img"
      aria-label="Cyrus"
      dangerouslySetInnerHTML={{ __html: markInner(id) }}
      {...props}
    />
  );
}

