/** Seconds between neighbouring traces firing: one sweep round all eight is 1.6s (see .brain-* CSS). */
const STAGGER = 0.2;

/**
 * The circuit brain in the brand gradient. While `active` it thinks: signals fire out from the chip
 * along each trace in a clockwise sweep, lighting every node they reach, as the chip's core pulses.
 * With `gradient={false}` it takes the text colour instead, like any other icon.
 */
export function ThinkingBrain({
  active = true,
  gradient = true,
  className = "",
  ...props
}: IconProps & { active?: boolean; gradient?: boolean }) {
  // Nxeon: one shared id. Every instance defines the identical userSpaceOnUse gradient, so any of
  // them resolves the same; a useId() here came out different on the server and the client inside
  // the portal frame (light theme), which React reports as a hydration mismatch.
  const gid = "cy5-brain-g";
  const ink = gradient ? `url(#${gid})` : "currentColor";
  const { chip, core } = BRAIN;
