    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox="0 0 24 24"
      width="1em"
      height="1em"
      fill="none"
      stroke={ink}
      strokeWidth={BRAIN_STROKE}
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden
      focusable="false"
      className={`brain${active ? " is-thinking" : ""} ${className}`}
      {...props}
