/** Everything a core shader animates from, computed once per frame. */
export interface CoreFrame {
  time: number;
  swirl: number;
  tilt: number;
  tiltX: number;
  energy: number;
  pulse: number;
  kick: number;
  impulse: number;
  kicks: number;
  waveR: number[];
  waveS: number[];
  waveAge: number[];
  waveSeed: number[];
}

const seedOf = (t: number) => {
  const x = Math.sin(t * 12.9898) * 43758.5453;
  return x - Math.floor(x);
};

/**
 * Turns the effects bus (typing energy, keystroke kicks, forge mode) into shader inputs.
 * Owns the accumulated values (spin, spring) so they never jump.
 */
export function createCoreDriver() {
  const st = { born: performance.now(), swirl: 0, imp: 0, impV: 0, lastKick: 0, count: 0 };
  return function frame(now: number, dt: number): CoreFrame {
    const age = (now - st.born) / 1000;
    const e = fx.energy;
    const mode = fx.mode;
    const t = now / 1000;
    const pulse =
      mode === "forging"
        ? Math.pow(0.5 + 0.5 * Math.sin(t * Math.PI * 2 * 1.25), 6)
        : mode === "thinking"
          ? Math.pow(0.5 + 0.5 * Math.sin(t * Math.PI * 2 * 0.9), 4) * 0.7
          : (0.5 + 0.5 * Math.sin(t * Math.PI * 2 * 0.2)) * 0.2;
    const f = mode === "forging" ? 1 : mode === "thinking" ? 0.6 : 0;

    // New keystrokes jolt the spring.
    for (const k of fx.kicks) {
      if (k > st.lastKick) {
        st.lastKick = k;
        st.count++;
        st.impV += 5.5;
      }
    }
    const acc = -70 * st.imp - 7.5 * st.impV;
    st.impV += acc * dt;
    st.imp += st.impV * dt;
    st.swirl += dt * (0.22 + e * 1.1 + f * 0.6);

    fx.kicks = fx.kicks.filter((k) => now - k < 1600);
    const waveR = [0, 0, 0, 0];
    const waveS = [0, 0, 0, 0];
    const waveAge = [0, 0, 0, 0];
    const waveSeed = [0, 0, 0, 0];
    let kick = 0;
    fx.kicks.slice(-4).forEach((k, i) => {
      const a = (now - k) / 1000;
      waveR[i] = 0.08 + a * 0.85;
      waveS[i] = Math.pow(Math.max(0, 1 - a / 1.4), 2) * 0.75;
      waveAge[i] = a;
      waveSeed[i] = seedOf(k);
      kick = Math.max(kick, Math.exp(-a * 7));
    });

    return {
      time: age,
      swirl: st.swirl,
      tilt: Math.sin(age * 0.3) * (0.42 + f * 0.08) + Math.sin(age * 0.11 + 1.7) * 0.12,
      tiltX: Math.sin(age * 0.23 + 0.5) * 0.13,
      energy: Math.min(1, e * 0.8 + f * 0.4),
      pulse,
      kick,
      impulse: st.imp,
      kicks: st.count,
      waveR,
      waveS,
      waveAge,
      waveSeed,
    };
  };
}

