function NavLink({ href, icon, label, badge, active, compact }: {
  href: string; icon: string; label: string; badge?: string; active: boolean; compact: boolean;
}) {
  return (
    <Link
      href={href}
      aria-current={active ? "page" : undefined}
      title={compact ? label : undefined}
      className={
        "nx-navlink group relative flex items-center rounded-[10px] transition-colors " +
        (compact ? "h-10 w-10 justify-center" : "h-11 gap-3 px-3 lg:h-[38px]") + " " +
        (active ? "nx-navlink-on" : "text-tx-dim hover:text-white")
      }
    >
      {/* 30% down from 19: the rail is the one place an icon repeats twenty times
          down a column, so it carries weight the page-level marks do not.
          Rest-vs-active glow (every icon keeps its own tone; rest is just
          quieter, via .nx-navlink:not(.nx-navlink-on) .nx-ico in globals.css)
          lives in CSS, not here — nothing else needed at this call site. */}
      <Icon name={icon} size={13} />
      {!compact && (
        <>
          <span className="flex-1 text-[13.5px] font-semibold">{label}</span>
          {badge && (
            <span className="rounded-[5px] bg-[rgba(140,58,233,0.22)] px-1.5 py-0.5 text-[9.5px] font-bold tracking-wide text-[#bfa8ee]">
              {badge}
            </span>
          )}
        </>
      )}
    </Link>
  );
}

function Rail({ compact, onNavigate, badges, extraNav = [] }: { compact: boolean; onNavigate?: () => void; badges: Badges; extraNav?: NavItem[] }) {
  const path = usePathname();
  /* extraNav: per-user entries (private previews) the layout resolves server
     side. They never live in the static NAV, so nobody else's rail or ⌘K
     palette ever contains them. */
  const extraHit = extraNav.find((n) => path === n.href || path.startsWith(n.href + "/"));
  const activeHref = extraHit ? (extraHit.subActive && path !== extraHit.href ? extraHit.subActive : extraHit.href) : activeNavHref(path);
  const navItems = extraNav.length ? [...NAV, ...extraNav] : NAV;
  /* Pages that mount a PlateBg. The rail has to know: over a plate it is glass,
     everywhere else it stays the solid panel it has always been. */
  const plated = path.startsWith("/dashboard/refer");
  /* overflow-x-hidden alongside overflow-y-auto: this list's scrollWidth
     measures 1px wider than its own clientWidth (a `scrollbar-width:none`
     + overflow:auto rounding quirk, not real content overflow) — with
     only the Y axis clipped, that 1px of horizontal "overflow" was
     visible as a bright hairline down the right edge of the dark
     sidebar, right over its own light-mode page background. */
  return (
    <nav className="noscroll flex h-full flex-col gap-0.5 overflow-y-auto overflow-x-hidden px-3 pb-4" onClick={onNavigate}>
      {GROUPS.map((g) => {
        const items = navItems.filter((n) => n.group === g);
        if (!items.length) return null;
        return (
          <div key={g} className="flex flex-col gap-px">
            {!compact && (
              <span className="mt-3 mb-0.5 px-3 text-[9.5px] font-bold uppercase tracking-[0.11em] text-tx-faint">
                {g}
              </span>
            )}
            {compact && <span className="mx-auto my-1.5 h-px w-6 bg-rim-soft" />}
            {items.map((n) => (
              <NavLink key={n.href} {...n} compact={compact}
                       badge={badges[n.href] ? String(badges[n.href]) : n.badge}
                       active={n.href === activeHref} />
