#!/usr/bin/env node
/**
 * Generates app/light-literals.generated.css — the light-theme counterpart of every
 * hard-coded hex colour utility (`text-[#a892ff]`, `bg-[#0a1630]`, `border-[#1b2a4a]`)
 * used by the customer portal.
 *
 * WHY: those literals were tuned against the dark page. Tailwind emits them as plain
 * colours, so no token swap can reach them. Instead of hand-writing one override per
 * literal (and forgetting the next one), this scans the portal sources and emits one rule
 * per distinct literal, with the light value derived from the dark one (same hue, lightness
 * pushed until it passes WCAG AA on a white card).
 *
 * Rules are scoped to `html[data-theme="light"]` and skip `.nx-dark-island` / `.nx-keep-dark`
 * subtrees (surfaces that stay dark in both themes), so dark mode is never touched.
 *
 *   node scripts/gen-light-literals.mjs          # rewrite the file
 *   node scripts/gen-light-literals.mjs --check  # exit 1 if the committed file is stale
 */
import { readFileSync, writeFileSync, readdirSync, statSync, existsSync } from "node:fs";
import { join, relative } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = join(fileURLToPath(import.meta.url), "..", "..");
const OUT = join(ROOT, "app/light-literals.generated.css");
// Whole UI tree: the portal also renders shared pieces from components/marketing (cookie
// banner, live chat) and components/portal; scanning everything keeps this exhaustive.
// Rules are scoped to light mode and skip dark islands, so unused ones are inert.
const SCAN = ["app", "components"];
const SKIP_DIR = new Set(["node_modules", "api", "newwebsitev1", "newwebsitev2", "newwebsitev3", "newwebsitev4", "newwebsitev5", "newwebsitev6", "newwebsitev7", "newwebsitev8"]);

function* walk(p) {
  const abs = join(ROOT, p);
  if (!existsSync(abs)) return;
  const st = statSync(abs);
  if (st.isFile()) { yield abs; return; }
  for (const f of readdirSync(abs)) {
    if (SKIP_DIR.has(f) || f.startsWith(".")) continue;
    yield* walk(join(p, f));
  }
}

