/* ═══ CYRUS v5 · the owner's redesign (handoff 2026-10-08) ═══════════════════════════════════
   Source: /tank/handoffs/cyrus/cyrus-handoff/cyrus/app/globals.css + network.css, carried over
   pixel-for-pixel and SCOPED so nothing reaches the rest of the portal:
   - every rule hangs off .cyrus-root (the wrapper in app/dashboard/cyrus/layout.tsx);
   - the handoff's :root tokens live on .cyrus-root, its `.light` theme follows the PORTAL theme
     (html[data-theme="light"], set by components/nx/ThemeToggle.tsx), never its own toggle;
   - its body lock (height:100%, overflow:hidden) is the root's own box, not <body>;
   - class names that also exist in the portal's globals (.glass, .btn-ghost, .kbd) are cy5-*;
   - @keyframes / @property are global, so they carry a cy5- prefix.
   The root is also `.nx-dark-island`: Cyrus has its own deliberate light theme, so the portal's
   generated light-mode retargeting (app/light-literals.generated.css) must not touch it.
   Regenerated from the handoff with a scoping script; edit here from now on. */

.cyrus-root {
  position: relative;
  height: 100%;
  min-height: 520px;
  overflow: hidden;
  isolation: isolate;
  /* The handoff positions its chrome with position:fixed against the viewport. Layout
     containment makes this box the containing block instead, so the studio fills the portal's
     content area (sidebar + top bar stay) without rewriting a single component. */
  container-type: size;
  contain: layout paint;
  font-family: var(--font-inter), ui-sans-serif, system-ui, sans-serif;
    color 0.4s ease,
    fill 0.4s ease,
    box-shadow 0.5s ease !important;
}

/* ───────────────────────── Surfaces ───────────────────────── */

.cyrus-root .cy5-glass {
  background: linear-gradient(180deg, var(--surface-2), var(--surface));
  backdrop-filter: blur(14px) saturate(140%);
  -webkit-backdrop-filter: blur(14px) saturate(140%);
  border: 1px solid var(--line);
  box-shadow: var(--panel-shadow);
}

/* No backdrop-filter: small chips sit over a canvas that redraws every frame, and
   re-blurring a dozen of them per frame is what made the page stutter. */
.cyrus-root .glass-soft {
  background: var(--surface-soft);
  border: 1px solid var(--line);
}

.cyrus-root .hairline-top {
  position: relative;
}
.cyrus-root .hairline-top::before {
  content: "";
  position: absolute;
  inset: 0 12% auto 12%;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgb(var(--glow) / 0.55), rgb(103 232 249 / 0.45), transparent);
  pointer-events: none;
}
html[data-theme="light"] .cyrus-root .hairline-top::before {
  background: linear-gradient(90deg, transparent, rgb(124 58 237 / 0.35), rgb(8 145 178 / 0.3), transparent);
}

.cyrus-root .topbar-logo {
  filter: drop-shadow(0 0 8px rgb(139 92 246 / 0.45));
}
html[data-theme="light"] .cyrus-root .topbar-logo {
  filter: none;
}

.cyrus-root .text-glow {
  text-shadow: 0 0 18px rgb(var(--glow) / 0.55);
}
html[data-theme="light"] .cyrus-root .text-glow {
  text-shadow: none;
}

.cyrus-root .tint {
  --cc: rgb(var(--c));
  --cc-ink: color-mix(in oklab, rgb(var(--c)) 55%, white);
}
html[data-theme="light"] .cyrus-root .tint {
  --cc: color-mix(in oklab, rgb(var(--c)) 70%, #1b1236);
  --cc-ink: color-mix(in oklab, rgb(var(--c)) 62%, #1b1236);
}

.cyrus-root .cy5-btn-ghost {
  display: block;
  width: 2.5px;
  border-radius: 2px;
  background: currentColor;
  animation: cy5-mic-bar 0.9s ease-in-out infinite;
