        break;
      }

      case "error":
        throw new Error(ev.message);
    }
  };
  return { handle, stop };
}

function finishFx(modId: string, ctx: Ctx) {
  fx.stopStream();
  fx.setMode("idle");
  fx.burst(modId, ctx.rgb);
  fx.packets([...ctx.path].reverse(), 5, { rgb: "196 181 253", speed: 1.3, gap: 0.12 });
  window.setTimeout(() => fx.ripple(true), 900);
}

async function readStream(res: Response, handle: (ev: GenEvent) => void) {
  const reader = res.body!.getReader();
  const decoder = new TextDecoder();
  let buffer = "";
  for (;;) {
    const { done, value } = await reader.read();
    if (done) break;
    buffer += decoder.decode(value, { stream: true });
    let nl: number;
    while ((nl = buffer.indexOf("\n")) >= 0) {
      const line = buffer.slice(0, nl).trim();
      buffer = buffer.slice(nl + 1);
      if (line) handle(JSON.parse(line) as GenEvent);
    }
  }
}

class HttpError extends Error {
  constructor(message: string, readonly json: Record<string, unknown>) {
    super(message);
  }
}

/** Run one forge request, and keep following a real build if the connection drops. */
async function run(open: (signal: AbortSignal) => Promise<Response>, ctx: Ctx) {
  const { handle, stop } = makeHandler(ctx);
  controller = new AbortController();
  const signal = controller.signal;
  try {
    let res = await open(signal);
    for (let attempt = 0; ; attempt++) {
      if (!res.ok || !res.body) {
        const j = (await res.json().catch(() => ({ error: res.statusText }))) as Record<string, unknown>;
        throw new HttpError(String(j.error ?? "The forge did not respond"), j);
      }
      await readStream(res, handle);
      if (ctx.finished) break;
      // A real build outlives the connection: re-attach (the server re-sends the code so far).
      const job = useStore.getState().job;
      if (!job?.buildId || attempt >= 4 || signal.aborted) throw new Error("The stream ended before the mod was packaged");
      await new Promise((r) => setTimeout(r, 1200 * (attempt + 1)));
      patchJob(() => ({ files: [], steps: [] }));
      res = await fetch(`/api/cyrus/generate?follow=${encodeURIComponent(job.buildId)}`, { signal });
    }
  } catch (err) {
    stop();
    const aborted = signal.aborted;
    const s = useStore.getState();
    const real = !!s.job?.real || !!s.job?.buildId;
    fx.stopStream();
    fx.setMode("idle");
    if (err instanceof HttpError) cyrusTokens.handleBuildError(err.json);
    useStore.setState((st) => ({
      // A brand-new template mod that never finished packaging shouldn't linger as an empty node.
      userMods: ctx.createdModId ? st.userMods.filter((m) => m.id !== ctx.createdModId) : st.userMods,
      job: st.job ? { ...st.job, status: aborted ? "cancelled" : "error", error: aborted ? undefined : String((err as Error).message), finishedAt: Date.now() } : null,
    }));
    if (ctx.createdModId) useStore.getState().select({ level: "category", gameId: s.job?.gameId, category: s.job?.category }, { openPanel: false });
    if (real) {
      void s.refreshReal();
      void cyrusTokens.refresh();
    }
    s.toast(
      aborted
        ? { tone: "info", title: real ? "Build stopped" : "Forge stopped", body: real ? "Cyrus stopped the build. Tokens it didn't use go back to you." : "Nothing was saved." }
        : { tone: "error", title: real ? "Didn't build" : "Forge failed", body: (err as Error).message },
    );
  } finally {
    controller = null;
  }
}

export async function forge(prompt: string, images: ForgeImage[] = []) {
  const state = useStore.getState();
  if (isJobLive(state.job)) return;
  const text = prompt.trim();
  if (!text) return;
  const model = MODEL_BY_ID[state.model];

  const sel = state.selection;
  const picked = sel.level === "mod" ? findMod(sel.modId) : undefined;
  // An idea pill is a prompt, not a mod: a forge from it is a brand-new mod in its category.
  const refineMod = picked?.idea ? undefined : picked;
  if (refineMod?.real && !refineMod.real.headBuildId) {
    state.toast({
      tone: "error",
      title: "Nothing to change yet",
      body: refineMod.real.running ? "Cyrus is still building this mod. Ask for the next change when it's ready." : "This mod has no version that built. Describe it again to forge a new one.",
    });
    return;
  }
  const prior = refineMod ? versionsOf(refineMod, state.userVersions) : [];
  const context = refineMod
    ? { gameId: refineMod.gameId, category: refineMod.category, modId: refineMod.id, modName: refineMod.name, version: prior.length + 1 }
    : { gameId: sel.gameId, category: sel.category };

  const ctx: Ctx = { createdModId: null, path: [], rgb: "167 139 250", finished: false, startedAt: performance.now() };
  useStore.setState({
    job: {
      id: "pending",
      status: "connecting",
      prompt: text,
      model: model.id,
      images: images.map((i) => i.url),
      credits: 0,
      refining: !!refineMod,
      version: refineMod ? prior.length + 1 : 1,
      steps: [],
      files: [],
      startedAt: Date.now(),
    },
  });
  fx.setMode("thinking");
  fx.ripple(true);

  await run(
    (signal) =>
      fetch("/api/cyrus/generate", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          prompt: text,
          model: model.id,
          images: images.length,
          attachmentIds: images.map((i) => i.uploadId).filter(Boolean),
          mcVersion: state.mcVersion,
          context,
          games: state.customGames,
        }),
        signal,
      }),
    ctx,
  );
}

/** Re-attach to a real build that is still running (page load, a build started elsewhere). */
export async function followForge(buildId: string) {
  const state = useStore.getState();
  if (isJobLive(state.job)) return;
  const b = state.realBuilds.find((x) => x.id === buildId);
  if (!b) return;
  const mod = findMod(realModId(b.rootBuildId ?? b.id));
  const n = mod ? versionsOf(mod, state.userVersions).findIndex((v) => v.id === buildId) + 1 : 1;
  useStore.setState({
    job: {
      id: buildId,
      status: "connecting",
      prompt: b.changeRequest || b.prompt,
      model: ((b.cyrus as { model?: ModelId } | null)?.model ?? "saka") as ModelId,
      images: [],
      credits: 0,
      refining: !!b.baseBuildId,
      version: Math.max(1, n),
      steps: [],
      files: [],
      startedAt: Date.parse(b.createdAt) || Date.now(),
      buildId,
      real: true,
    },
  });
  fx.setMode("thinking");
  const ctx: Ctx = { createdModId: null, path: [], rgb: "167 139 250", finished: false, startedAt: performance.now() };
  await run((signal) => fetch(`/api/cyrus/generate?follow=${encodeURIComponent(buildId)}`, { signal }), ctx);
}

/** Utility for UI: the category label + game for a job, once routed. */
export function jobRouteLabel(job: Job) {
  if (!job.gameId || !job.category) return null;
  return `${getGame(job.gameId)?.short ?? "Game"} › ${CATEGORY_BY_KEY[job.category].label}`;
}

