export const REAL_PREFIX = "nx-";
export const realModId = (rootId: string) => `${REAL_PREFIX}${rootId}`;
export const isRealModId = (id: string | undefined | null): id is string => !!id && id.startsWith(REAL_PREFIX);
export const rootOfRealMod = (id: string) => id.slice(REAL_PREFIX.length);

/** The category branches a real game may grow: its own plus at most this many more. */
const MAX_EXTRA_CATEGORIES = 2;
const FALLBACK: CategoryKey = "mechanics";

const escapeRe = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
const hasWord = (text: string, word: string) => new RegExp(`(^|[^a-z0-9])${escapeRe(word)}(s|es)?([^a-z0-9]|$)`).test(text);

/** Same keyword scoring the forge router uses (lib/cyrus/engine routePrompt), over the build's own words. */
export function scoreCategory(text: string): CategoryKey | null {
  const p = text.toLowerCase();
  let best: CategoryKey | null = null;
  let bestScore = 0;
  for (const c of CATEGORIES) {
    let score = 0;
    for (const k of c.keywords) if (hasWord(p, k)) score += k.length;
    if (score > bestScore) { bestScore = score; best = c.key; }
  }
  return best;
}

const projectText = (p: CyrusProject) => {
  const head = p.head ?? p.latest;
  const s = head.result?.summary;
  return [p.title, head.pluginName, s?.tagline, s?.text, p.builds[0]?.prompt].filter(Boolean).join(" \n ");
};

