// Cyrus v6: which games can join the network ring (pure, client-safe, unit-tested).
//
// The owner's rule (2026-10-08): "the add game needs to be limited to the games that we actually
// support". No free-text custom games any more. A game is a candidate when it is in the Cyrus
// registry (lib/cyrus/games.ts, the same list the token economy and the mod store read) and is not
// on the ring yet. It is ADDABLE only when Cyrus can forge for it, i.e. a ring preset exists for it
// (a GAMES row in lib/cyrus/data.ts: branch colour, logo, toolchain, generator template). A
// registry game with no generator yet ("Coming soon") is listed but cannot be added.
//
// When nothing is addable, the studio hides the dashed "Add game" branch, the top-bar button and
// the palette action rather than opening a dialog that is a dead end.
import { CYRUS_GAMES, type CyrusGame } from "./games";
import { GAMES } from "./data";
import type { Game } from "./types";

export type RingCandidate = {
  id: string;
  name: string;
  status: CyrusGame["status"];
  loader: string;
  builds: string;
  /** The branch to add, when Cyrus can forge for this game. */
  preset: Game | null;
};

/**
 * Supported games not on the ring, addable ones first.
 * `presets` are the ring definitions Cyrus has a generator for (defaults to GAMES); `registry` is
 * the Cyrus game registry (defaults to CYRUS_GAMES). Both are parameters so tests can vary them.
 */
export function ringCandidates(onRing: readonly Pick<Game, "id">[], registry: readonly CyrusGame[] = CYRUS_GAMES, presets: readonly Game[] = GAMES): RingCandidate[] {
  const have = new Set(onRing.map((g) => g.id));
  const byId = new Map(presets.map((p) => [p.id, p]));
  const out: RingCandidate[] = [];
  const seen = new Set<string>();
  for (const r of registry) {
    if (have.has(r.id) || seen.has(r.id)) continue;
    seen.add(r.id);
    out.push({ id: r.id, name: r.name, status: r.status, loader: r.loader, builds: r.builds, preset: byId.get(r.id) ?? null });
  }
  // A ring preset whose registry row has not landed yet still counts as supported (template preview).
  for (const p of presets) {
    if (have.has(p.id) || seen.has(p.id)) continue;
    seen.add(p.id);
    out.push({ id: p.id, name: p.name, status: p.real ? "live" : "soon", loader: p.toolchain.split("·")[0].trim(), builds: p.blurb, preset: p });
  }
  return out.sort((a, b) => Number(!!b.preset) - Number(!!a.preset) || a.name.localeCompare(b.name));
}

/** True when at least one supported game can still be added to the ring. */
export const canAddGame = (onRing: readonly Pick<Game, "id">[], registry?: readonly CyrusGame[], presets?: readonly Game[], max = Infinity) =>
  onRing.length < max && ringCandidates(onRing, registry, presets).some((c) => !!c.preset);

/** Plain label for a candidate's status in the dialog. */
export function candidateStatus(c: RingCandidate): string {
  if (!c.preset) return "Coming soon";
  return c.preset.real ? "Live" : "Template preview";
}

