"use client";

import { useEffect, useMemo } from "react";
import { GameEmblem } from "@/components/cyrus/icons/GameEmblems";
import { CloseIcon, PlusIcon } from "@/components/cyrus/icons/ui";
import { MAX_GAMES } from "@/lib/cyrus/data";
import { fx } from "@/lib/cyrus/fx";
import { candidateStatus, ringCandidates, type RingCandidate } from "@/lib/cyrus/ring";
import { CORE_ID, useGames, useStore } from "@/lib/cyrus/store";

/**
 * v6: "Add game" only offers games Cyrus actually supports (lib/cyrus/ring.ts). There is no free-text
 * custom game any more. Branches added before v6 stay on the ring (their local mods are kept) and can
 * still be removed from their branch overview. The dialog is only reachable while something is
 * addable; the ring hides the dashed branch otherwise.
 */
export function AddGameDialog() {
  const open = useStore((s) => s.addGameOpen);
  const setOpen = useStore((s) => s.setAddGameOpen);
  const addGame = useStore((s) => s.addGame);
  const select = useStore((s) => s.select);
  const toast = useStore((s) => s.toast);
  const games = useGames();
  const list = useMemo(() => ringCandidates(games), [games]);
  const full = games.length >= MAX_GAMES;

  useEffect(() => {
    if (!open) return;
    const k = (e: KeyboardEvent) => e.key === "Escape" && setOpen(false);
    window.addEventListener("keydown", k);
    return () => window.removeEventListener("keydown", k);
  }, [open, setOpen]);

  if (!open) return null;

  const add = (c: RingCandidate) => {
    const g = c.preset;
    if (!g || full) return;
    addGame(g);
    setOpen(false);
    window.setTimeout(() => {
      select({ level: "game", gameId: g.id });
      fx.packets([CORE_ID, g.id], 5, { rgb: g.rgb, speed: 1.4, size: 1.5, gap: 0.12 });
      fx.ripple(true);
    }, 60);
    window.setTimeout(() => fx.burst(g.id, g.rgb), 900);
    toast({ tone: "success", title: `${g.name} joined the network`, body: `${g.toolchain} · ${candidateStatus(c)}`, rgb: g.rgb });
  };

  return (
    <div
      className="animate-fade fixed inset-0 z-[60] flex items-start justify-center overflow-y-auto bg-[rgb(3_3_10/0.55)] px-3 py-[8cqh] backdrop-blur-[6px] cy-light:bg-[rgb(91_33_182/0.08)]"
      onPointerDown={() => setOpen(false)}
    >
      <div role="dialog" aria-label="Add a game branch" className="cy5-solid animate-rise hairline-top w-full max-w-[560px] overflow-hidden rounded-3xl" onPointerDown={(e) => e.stopPropagation()}>
        <div className="flex items-start gap-3 border-b border-cy-line p-5">
          <div className="min-w-0 flex-1">
            <h2 className="font-cy-display text-[19px] font-semibold text-cy-ink">Add a game branch</h2>
            <p className="mt-1 text-[12.5px] leading-relaxed text-cy-ink-2">Games Cyrus supports that aren&apos;t on your network yet. Prompts that mention a game route straight to its branch.</p>
          </div>
          <button type="button" onClick={() => setOpen(false)} className="cy5-btn-ghost h-8 w-8 text-cy-muted" aria-label="Close">
            <CloseIcon />
          </button>
        </div>
        <ul className="max-h-[60cqh] divide-y divide-cy-line overflow-y-auto">
          {list.map((c) => {
            const rgb = c.preset?.rgb ?? "149 140 192";
            return (
              <li key={c.id} className="tint flex items-center gap-3 px-5 py-3.5" style={{ ["--c" as string]: rgb }}>
                <span className="grid h-11 w-11 shrink-0 place-items-center rounded-2xl text-[24px]" style={{ color: "var(--cc)", background: `rgb(${rgb} / 0.12)`, boxShadow: `inset 0 0 0 1px rgb(${rgb} / 0.4)` }}>
                  {c.preset ? <GameEmblem emblem={c.preset.emblem} logo={c.preset.logo} logoTone={c.preset.logoTone} /> : <span className="font-cy-display text-[13px] font-bold">{c.name.slice(0, 2).toUpperCase()}</span>}
                </span>
                <span className="min-w-0 flex-1">
                  <span className="flex items-center gap-2">
                    <span className="truncate font-cy-display text-[14px] font-semibold text-cy-ink">{c.name}</span>
                    <span className={`shrink-0 rounded-full px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wider ${c.preset ? "bg-[rgb(var(--glow)/0.14)] text-cy-accent-ink" : "bg-[rgb(var(--glow)/0.06)] text-cy-muted"}`}>
                      {candidateStatus(c)}
                    </span>
                  </span>
                  <span className="block truncate text-[11.5px] text-cy-muted">
                    {c.loader} · {c.builds}
                  </span>
                </span>
                <button
                  type="button"
                  disabled={!c.preset || full}
                  onClick={() => add(c)}
                  className="inline-flex h-8 shrink-0 items-center gap-1.5 rounded-xl px-3 text-[12px] font-semibold text-white transition enabled:hover:brightness-110 disabled:opacity-35"
                  style={{ background: `linear-gradient(135deg, rgb(${rgb}), #6366f1)` }}
                  title={!c.preset ? "Cyrus can't forge for this game yet" : full ? `The network holds ${MAX_GAMES} games` : undefined}
                >
                  <PlusIcon /> Add
                </button>
              </li>
            );
          })}
          {!list.length && <li className="px-5 py-8 text-center text-[13px] text-cy-muted">Every game Cyrus supports is already on your network.</li>}
        </ul>
        {full && <p className="border-t border-cy-line px-5 py-3 text-[11.5px] text-rose-400">The network holds {MAX_GAMES} games. Remove an added branch to make room.</p>}
      </div>
    </div>
  );
}

