/* Cyrus brand pieces that render anywhere (studio, NxLabs, marketing): theme-swapped images.
   The portal theme lives on html[data-theme="light"]; a component can also pin a theme. */
.cyrus-themed { display: inline-flex; align-items: center; line-height: 0; }
.cyrus-themed > img { display: block; height: 100%; width: auto; max-width: none; user-select: none; -webkit-user-drag: none; }
.cyrus-themed[data-theme="auto"] > .is-light { display: none; }
html[data-theme="light"] .cyrus-themed[data-theme="auto"] > .is-light { display: block; }
html[data-theme="light"] .cyrus-themed[data-theme="auto"] > .is-dark { display: none; }

/* The neon loading coin: face -> three-quarter -> edge -> three-quarter (mirrored) -> face. */
.cyrus-coinspin { position: relative; display: inline-block; flex-shrink: 0; }
.cyrus-coinspin > img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: contain; opacity: 0; animation: cyrus-coin-frame 1.2s steps(1, end) infinite; }
.cyrus-coinspin > img:nth-child(1) { animation-delay: 0s; }
.cyrus-coinspin > img:nth-child(2) { animation-delay: -1.05s; }
.cyrus-coinspin > img:nth-child(3) { animation-delay: -0.9s; }
.cyrus-coinspin > img:nth-child(4) { animation-delay: -0.75s; transform: scaleX(-1); }
@keyframes cyrus-coin-frame {
  0% { opacity: 1; }
  12.5% { opacity: 1; }
  12.51% { opacity: 0; }
  100% { opacity: 0; }
}
.cyrus-coinspin.is-smooth > img { animation-name: cyrus-coin-fade; animation-timing-function: ease-in-out; }
@keyframes cyrus-coin-fade {
  0% { opacity: 0; }
  6% { opacity: 1; }
  19% { opacity: 1; }
  25% { opacity: 0; }
  100% { opacity: 0; }
}
@media (prefers-reduced-motion: reduce) {
  .cyrus-coinspin > img { animation: none; opacity: 0; }
  .cyrus-coinspin > img:first-child { opacity: 1; }
}
EOF
