import { CYRUS_BRAND } from "@/lib/cyrus/brand";
import "./brand.css";

export type BuiltWithCyrusVariant = "generic" | "tested" | "compact";

/**
 * "Built with Cyrus" badge, the owner's artwork (docs/cyrus/asset-picks.json "built-with-cyrus").
 *  - generic: the round-end pill, for any mod made with Cyrus.
 *  - tested:  the laurel seal. ONLY for community mods that are highly tested and rated; the caller
 *             decides that from real data, never by default.
 *  - compact: the shield, the generic badge where space is tight.
 * `theme="auto"` follows the portal theme (html[data-theme="light"]); pin "dark" or "light" on
 * surfaces with a fixed background. `height` is in px; the width follows the artwork.
 */
export function BuiltWithCyrusBadge({
  variant = "generic",
  theme = "auto",
  height,
  className = "",
  title,
}: {
  variant?: BuiltWithCyrusVariant;
  theme?: "auto" | "dark" | "light";
  height?: number;
  className?: string;
