import type { SVGProps } from "react";
import type { ModelId } from "@/lib/cyrus/types";

/**
 * Cyrus model glyphs (v6): one tier language for Katara, Saka and Yakko, the models' original
 * names. Each is a cluster of forge crystals: Katara one, Saka two, Yakko three. Same 24-unit grid,
 * same 1.5 outline, same facet line, so they read as a set and the tier is the number of crystals.
 *
 *  - variant "gradient": the brand version (each model's own cyan / indigo / magenta ramp with a
 *    white edge light). Used in the model picker, the plans cards, the prompt dock, the token chip.
 *  - variant "mono": currentColor outline + 20% fill, for tinted chips and small inline marks.
 *
 * Standalone copies of the same paths: public/cyrus/models/{katara,saka,yakko}.svg (gradient) and
 * {id}-mono.svg (currentColor). The marketing page imports this component or those files.
 */

type Crystal = { outline: string; facet: string };

export const MODEL_CRYSTALS: Record<ModelId, Crystal[]> = {
  katara: [{ outline: "M8.3 20.1L8.3 8.4L12 3.6L15.7 8.4L15.7 20.1L12 21Z", facet: "M12 3.6L11.41 9.6L12 20.4" }],
  saka: [
    { outline: "M5.76 20.55L3.69 12.27L5.46 8.13L8.96 10.95L11.03 19.23L8.61 20.74Z", facet: "M5.46 8.13L6.19 12.84L8.46 20.17" },
    { outline: "M12 19.34L14.04 7.78L17.84 4.12L20.16 8.86L18.12 20.42L14.91 20.74Z", facet: "M17.84 4.12L16.41 9.38L15.01 20.17" },
  ],
  yakko: [
    { outline: "M4.92 20.28L1.67 14.64L2.06 11.27L5.17 12.62L8.43 18.26L7.07 19.96Z", facet: "M2.06 11.27L3.67 14.71L6.81 19.5" },
    { outline: "M15.57 18.26L18.83 12.62L21.94 11.27L22.33 14.64L19.08 20.28L16.93 19.96Z", facet: "M21.94 11.27L19.77 14.38L17.19 19.5" },
    { outline: "M9.54 19.16L9.54 7.81L12 4.29L14.46 7.81L14.46 19.16L12 19.96Z", facet: "M12 4.29L11.61 8.87L12 19.43" },
  ],
};

/** Each model's gradient ramp (light top, model hue, deep base). */
export const MODEL_RAMP: Record<ModelId, [string, string, string]> = {
  katara: ["#d6fdff", "#22d3ee", "#1e40af"],
  saka: ["#e6e9ff", "#818cf8", "#4c1d95"],
  yakko: ["#ffe4f8", "#e879f9", "#701a75"],
};

export type ModelGlyphVariant = "gradient" | "mono";
type P = Omit<SVGProps<SVGSVGElement>, "id"> & { size?: number | string; variant?: ModelGlyphVariant; title?: string };

/** Renders the mark for a Cyrus model. Size defaults to 1em, like the other studio icons. */
export function ModelGlyph({ id, size = "1em", variant = "gradient", title, className, ...props }: { id: ModelId } & P) {
  const crystals = MODEL_CRYSTALS[id] ?? MODEL_CRYSTALS.saka;
  // One stable id per model: every instance defines the identical userSpaceOnUse gradient, so any
  // of them resolves the same (a useId() here differed server/client, see ThinkingBrain).
  const gid = `cyrus-model-${id}-g`;
  const ramp = MODEL_RAMP[id] ?? MODEL_RAMP.saka;
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox="0 0 24 24"
      width={size}
      height={size}
      fill="none"
      role={title ? "img" : undefined}
      aria-label={title}
      aria-hidden={title ? undefined : true}
      focusable="false"
      className={`cy-model-glyph ${className ?? ""}`}
      data-model={id}
      data-variant={variant}
      {...props}
    >
      {variant === "gradient" ? (
        <>
          <defs>
            <linearGradient id={gid} x1="6" y1="3" x2="17" y2="22" gradientUnits="userSpaceOnUse">
              <stop offset="0" stopColor={ramp[0]} />
              <stop offset=".48" stopColor={ramp[1]} />
              <stop offset="1" stopColor={ramp[2]} />
            </linearGradient>
          </defs>
          {crystals.map((c, i) => (
            <g key={i} strokeLinejoin="round">
              <path d={c.outline} fill={`url(#${gid})`} stroke={`url(#${gid})`} strokeWidth={0.9} />
              <path d={c.outline} stroke="#fff" strokeOpacity={0.5} strokeWidth={0.55} />
              <path d={c.facet} stroke="#fff" strokeOpacity={0.7} strokeWidth={0.7} strokeLinecap="round" />
            </g>
          ))}
        </>
      ) : (
        crystals.map((c, i) => (
          <g key={i} stroke="currentColor" strokeLinejoin="round">
            <path d={c.outline} fill="currentColor" fillOpacity={0.2} strokeWidth={1.5} />
            <path d={c.facet} strokeOpacity={0.7} strokeWidth={1} strokeLinecap="round" />
          </g>
        ))
      )}
    </svg>
  );
}

export const KataraGlyph = (p: P) => <ModelGlyph id="katara" {...p} />;
export const SakaGlyph = (p: P) => <ModelGlyph id="saka" {...p} />;
export const YakkoGlyph = (p: P) => <ModelGlyph id="yakko" {...p} />;
export const MODEL_GLYPHS: Record<ModelId, (p: P) => React.JSX.Element> = { katara: KataraGlyph, saka: SakaGlyph, yakko: YakkoGlyph };
