content.content:
/* Cyrus tokens UI (components/cyrus-tokens/*). Every rule is on a cyt-* class, inside the
   studio's own token scope (.cy-app / .cy-tokens from app/dashboard/cyrus/cyrus.css), so
   nothing here can reach the portal, marketing or admin. */

@keyframes cyt-in { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: none; } }

.cyt-chipwrap { display: inline-flex; align-items: center; gap: 8px; }
.cyt-beta { font: 600 9px/1 var(--font-mono); letter-spacing: .14em; text-transform: uppercase; padding: 4px 7px; border-radius: 6px; color: #9fe9f7; background: rgba(20, 197, 228, .1); border: 1px solid rgba(20, 197, 228, .26); white-space: nowrap; }
.cyt-chip { display: inline-flex; align-items: center; gap: 7px; height: 32px; padding: 0 5px 0 10px; border-radius: 10px; font-size: 12.5px; color: var(--cy-ink2); border: 1px solid var(--cy-line); background: var(--cy-raise); transition: background .18s, border-color .18s, color .18s; white-space: nowrap; }
.cyt-chip:hover { color: var(--cy-ink); background: var(--cy-raise-2); border-color: var(--cy-line2); }
.cyt-chip b { font-weight: 650; color: var(--cy-ink); font-variant-numeric: tabular-nums; letter-spacing: -.01em; }
.cyt-chip-u { color: var(--cy-ink3); }
.cyt-chip-get { display: inline-flex; align-items: center; height: 22px; padding: 0 8px; border-radius: 7px; font-size: 11.5px; font-weight: 600; color: #fff; background: linear-gradient(110deg, #2f7eef, #8c3ae9 70%); }
.cyt-chip.low { border-color: rgba(255, 180, 79, .45); }
.cyt-chip.low b { color: var(--cy-warn); }
.cyt-chipwrap.compact .cyt-chip { height: 30px; padding-left: 8px; }
.cyt-chipwrap.compact .cyt-chip-get { padding: 0 7px; }

.cy-est.cyt-est { display: inline-flex; align-items: center; gap: 5px; }
.cy-est.cyt-est.warn { color: var(--cy-warn); }
.cyt-est-get { margin-left: 4px; font-size: 11px; font-weight: 600; color: var(--cy-cyan, #22d3ee); text-decoration: underline; text-underline-offset: 2px; }

.cyt-lock { display: inline-flex; align-items: center; gap: 4px; font: 600 9px/1 var(--font-mono); letter-spacing: .08em; text-transform: uppercase; padding: 3px 6px; border-radius: 5px; color: #ffd28f; background: rgba(255, 180, 79, .12); }
.cyt-foot button { color: var(--cy-cyan, #22d3ee); font-weight: 600; text-decoration: underline; text-underline-offset: 2px; }

.cyt-notice { position: fixed; z-index: 95; left: 50%; bottom: 28px; transform: translateX(-50%); display: flex; align-items: center; gap: 10px; padding: 10px 12px 10px 14px; border-radius: 14px; font-size: 13px; color: var(--cy-ink); background: var(--cy-pop); border: 1px solid var(--cy-line2); box-shadow: var(--cy-shadow); animation: cyt-in .22s var(--cy-ease) both; max-width: calc(100vw - 32px); }
.cyt-notice button { color: var(--cy-ink3); font-size: 18px; line-height: 1; padding: 0 2px; }

.cyt-modal.cy-modal { max-width: 860px; gap: 16px; }
.cyt-head { display: flex; align-items: flex-start; gap: 12px; }
.cyt-head-l { display: flex; flex-direction: column; gap: 6px; min-width: 0; flex: 1; }
.cyt-title { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.cyt-title h2 { font-size: 19px; font-weight: 650; letter-spacing: -.02em; color: var(--cy-ink); }
.cyt-sub { font-size: 12.5px; line-height: 1.5; color: var(--cy-ink3); max-width: 62ch; }

.cyt-balance { display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap; padding: 14px 16px; border-radius: 16px; border: 1px solid var(--cy-line); background: radial-gradient(120% 140% at 0% 0%, rgba(140, 58, 233, .2), transparent 60%), var(--cy-raise); }
.cyt-balance.low { border-color: rgba(255, 180, 79, .35); }
.cyt-bal-n { display: flex; align-items: baseline; gap: 10px; flex-wrap: wrap; }
.cyt-bal-n b { font-size: 34px; font-weight: 700; letter-spacing: -.035em; color: var(--cy-ink); font-variant-numeric: tabular-nums; }
.cyt-balance.low .cyt-bal-n b { color: var(--cy-warn); }
.cyt-bal-n span { font-size: 12.5px; color: var(--cy-ink3); }
.cyt-bal-m { display: flex; flex-direction: column; align-items: flex-end; gap: 6px; }
.cyt-bal-sub { font-size: 11.5px; color: var(--cy-ink3); }

.cyt-models { display: inline-flex; flex-wrap: wrap; gap: 6px; }
.cyt-model { display: inline-flex; align-items: center; gap: 6px; height: 22px; padding: 0 8px; border-radius: 7px; font-size: 11.5px; font-weight: 550; color: var(--cy-ink2); background: var(--cy-raise); border: 1px solid var(--cy-line); }
.cyt-model i { width: 7px; height: 7px; border-radius: 50%; }
.cyt-model.off { opacity: .42; text-decoration: line-through; text-decoration-color: rgba(180, 188, 224, .5); }

.cyt-reason { font-size: 12.5px; line-height: 1.5; padding: 10px 12px; border-radius: 12px; color: #ffe1b3; background: rgba(255, 180, 79, .1); border: 1px solid rgba(255, 180, 79, .28); }
.cyt-tabs { display: flex; gap: 4px; padding: 3px; border-radius: 11px; background: var(--cy-raise); border: 1px solid var(--cy-line); align-self: flex-start; }
.cyt-err { font-size: 12.5px; color: var(--cy-bad); }
.cyt-ok { font-size: 12.5px; color: var(--cy-ok); }
.cyt-fine { font-size: 11.5px; line-height: 1.55; color: var(--cy-ink4); }
.cyt-link { color: var(--cy-cyan, #22d3ee); font-weight: 600; text-decoration: underline; text-underline-offset: 2px; }

.cyt-plans { display: flex; flex-direction: column; gap: 12px; }
.cyt-plan-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 10px; }
.cyt-plan { position: relative; display: flex; flex-direction: column; gap: 10px; padding: 14px; border-radius: 16px; border: 1px solid var(--cy-line); background: var(--cy-raise); animation: cyt-in .2s var(--cy-ease) both; }
.cyt-plan.t-katara { --cyt-hue: #14c5e4; }
.cyt-plan.t-saka { --cyt-hue: #8c3ae9; }
.cyt-plan.t-all { --cyt-hue: #d623e1; }
.cyt-plan::before { content: ""; position: absolute; inset: 0 0 auto; height: 2px; border-radius: 16px 16px 0 0; background: linear-gradient(90deg, transparent, var(--cyt-hue), transparent); opacity: .8; }
.cyt-plan.cur { border-color: var(--cy-line2); background: var(--cy-raise-2); }
.cyt-plan-h { display: flex; align-items: center; gap: 8px; }
.cyt-plan-h b { font-size: 14.5px; font-weight: 650; color: var(--cy-ink); }
.cyt-plan-p { display: flex; align-items: baseline; gap: 4px; }
.cyt-plan-p b { font-size: 24px; font-weight: 700; letter-spacing: -.03em; color: var(--cy-ink); }
.cyt-plan-p span { font-size: 12px; color: var(--cy-ink3); }
.cyt-plan-t { display: inline-flex; align-items: center; gap: 6px; font-size: 12.5px; color: var(--cy-ink2); }
.cyt-plan-a { margin-top: auto; display: flex; }
.cyt-plan-a .cy-btn { width: 100%; }
.cyt-plan-note { font-size: 11.5px; color: var(--cy-ink3); }
.cyt-confirm { display: flex; flex-direction: column; gap: 6px; font-size: 11.5px; line-height: 1.45; color: var(--cy-ink2); width: 100%; }

.cyt-topup { display: flex; flex-direction: column; gap: 12px; }
.cyt-amounts { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 8px; }
.cyt-amt { display: flex; flex-direction: column; align-items: flex-start; gap: 3px; padding: 11px 12px; border-radius: 13px; border: 1px solid var(--cy-line); background: var(--cy-raise); text-align: left; transition: border-color .15s, background .15s; cursor: pointer; }
.cyt-amt b { font-size: 16px; font-weight: 650; color: var(--cy-ink); }
.cyt-amt span { font-size: 11px; color: var(--cy-ink3); }
.cyt-amt.on { border-color: rgba(140, 58, 233, .7); background: rgba(140, 58, 233, .14); }
.cyt-amt-k { font-size: 11px; color: var(--cy-ink3); }
.cyt-amt-in { display: inline-flex; align-items: center; gap: 2px; font-size: 16px; font-weight: 650; color: var(--cy-ink); }
.cyt-amt-in input { width: 100%; min-width: 0; background: transparent; border: 0; outline: 0; color: var(--cy-ink); font: inherit; }
.cyt-topup-go { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 10px 12px; border-radius: 13px; background: var(--cy-raise); border: 1px solid var(--cy-line); }
.cyt-topup-go > span { display: inline-flex; align-items: center; gap: 6px; font-size: 13px; color: var(--cy-ink2); }

.cyt-hist { display: flex; flex-direction: column; gap: 10px; max-height: 380px; overflow-y: auto; scrollbar-width: thin; }
.cyt-hist ul { display: flex; flex-direction: column; }
.cyt-hist li { display: grid; grid-template-columns: 58px minmax(0, 1fr) auto; gap: 10px; align-items: center; padding: 9px 4px; border-bottom: 1px solid var(--cy-line); font-size: 12.5px; }
.cyt-h-d { color: var(--cy-ink4); font-variant-numeric: tabular-nums; }
