content.content:
/* ═══ CYRUS · shared kit (token modal, install modal) ═════════════════════════════════════
   What the v4 studio stylesheet still provides now that the studio itself is v5 (studio.css):
   the token UI (components/cyrus-tokens, UI-CONTRACT.md: it reuses .cy-modal, .cy-btn, .cy-seg,
   .cy-tag, .cy-ib and the --cy-* variables) and the install-to-server modal
   (components/cyrus/kit/InstallModal.tsx). Both portal to <body> under .cy-tokens; inside the
   studio they read the same variables from .cyrus-root. The --cy-* palette is retuned to the v5
   look (handoff tokens: deep space #05030b, ink #f2eeff, violet #a78bfa, cyan #67e8f9). */
.cyrus-root, .cy-tokens {
  --cy-bg0: #05030b; --cy-bg1: #0a0617; --cy-bg2: #140b2b;
  --cy-ink: #f2eeff; --cy-ink2: #cfc7f0; --cy-ink3: #958cc0; --cy-ink4: #8a82b8;
  --cy-violet: #a78bfa; --cy-blue: #3b82ff; --cy-magenta: #e04dff; --cy-cyan: #67e8f9; --cy-green: #34e3a2;
  --cy-accent: #a78bfa; --cy-accent-ink: #c4b5fd; --cy-on-accent: #ffffff; --cy-accent-soft: rgba(167, 139, 250, .16); --cy-accent-line: rgba(167, 139, 250, .5);
  --cy-alert: #ff6b8a; --cy-alert-soft: rgba(255, 90, 130, .12); --cy-alert-line: rgba(255, 110, 150, .4);
  --cy-grad: linear-gradient(135deg, #8b5cf6, #6366f1 45%, #06b6d4);
  --cy-line: rgba(167, 139, 250, .13); --cy-line2: rgba(167, 139, 250, .26); --cy-line3: rgba(167, 139, 250, .38);
  --cy-thread: rgba(170, 180, 255, .35);
  --cy-side: rgba(7, 8, 28, .94);
  --cy-surface: rgba(15, 10, 32, .82); --cy-surface-2: rgba(22, 15, 46, .92); --cy-pop: #0e091e; --cy-solid: #0e091e;
  --cy-raise: rgba(167, 139, 250, .06); --cy-raise-2: rgba(167, 139, 250, .1); --cy-raise-3: rgba(167, 139, 250, .16);
  --cy-code-bg: rgba(6, 7, 26, .7); --cy-code-ink: #dfe3ff; --cy-code-n: #6f78ad;
  --cy-blur: blur(16px) saturate(1.3);
  --cy-shadow: 0 24px 60px -28px rgba(0, 0, 0, .85), inset 0 1px 0 rgba(255, 255, 255, .05);
  --cy-shadow-pop: 0 26px 70px -20px rgba(0, 0, 0, .9), 0 0 0 1px rgba(150, 160, 255, .14);
  --cy-glow: 0 0 22px -4px rgba(167, 139, 250, .6);
  --cy-ease: cubic-bezier(.2, .8, .2, 1);
  --cy-r-sm: 7px; --cy-r: 9px; --cy-r-md: 11px; --cy-r-lg: 14px;
  --cy-side-w: 200px; --cy-insp-w: clamp(400px, 27vw, 480px);
  --cy-ok: #34e3a2; --cy-warn: #ffb44f; --cy-bad: var(--cy-alert);
  color: var(--cy-ink); -webkit-font-smoothing: antialiased;
}

