cd /tank/dev-worktrees/cyrus-v6-studio; cat >> app/dashboard/cyrus/studio.css <<'EOF'

/* ═══ v6 (studio-ui) ═══════════════════════════════════════════════════════════════════════════ */

/* An OPAQUE floating surface (model picker, add-game dialog): legible over the moving network.
   The glass lives only on the edge: a gradient hairline border and a top shine. */
.cyrus-root .cy5-solid {
  position: relative;
  background: linear-gradient(180deg, color-mix(in srgb, var(--cy-pop) 92%, rgb(var(--glow))) 0%, var(--cy-pop) 38%) padding-box,
    linear-gradient(160deg, rgb(var(--glow) / 0.55), rgb(103 232 249 / 0.28) 40%, rgb(var(--glow) / 0.14) 70%, rgb(240 171 252 / 0.4)) border-box;
  border: 1px solid transparent;
  box-shadow: var(--cy-shadow-pop), 0 0 0 1px rgb(0 0 0 / 0.2);
  color: var(--cy-ink);
}
html[data-theme="light"] .cyrus-root .cy5-solid {
  background: linear-gradient(180deg, #faf8ff 0%, #ffffff 38%) padding-box,
    linear-gradient(160deg, rgb(124 58 237 / 0.45), rgb(8 145 178 / 0.25) 45%, rgb(124 58 237 / 0.12) 70%, rgb(192 38 211 / 0.3)) border-box;
  box-shadow: 0 22px 50px -18px rgb(76 29 149 / 0.32), 0 2px 6px rgb(76 29 149 / 0.08);
}

/* Model picker rows */
.cyrus-root .cy-mp-row { position: relative; display: flex; width: 100%; align-items: flex-start; gap: 12px; padding: 10px 12px; border-radius: 14px; text-align: left; border: 1px solid transparent; transition: background 0.15s, border-color 0.15s; }
.cyrus-root .cy-mp-row:hover, .cyrus-root .cy-mp-row:focus-visible { background: var(--cy-raise-2); outline: none; }
.cyrus-root .cy-mp-row[aria-selected="true"] { background: color-mix(in srgb, rgb(var(--c)) 13%, var(--cy-pop)); border-color: rgb(var(--c) / 0.55); box-shadow: inset 3px 0 0 rgb(var(--c)); }
html[data-theme="light"] .cyrus-root .cy-mp-row[aria-selected="true"] { background: color-mix(in srgb, rgb(var(--c)) 10%, #fff); }
.cyrus-root .cy-mp-row[data-locked="true"] .cy-mp-name, .cyrus-root .cy-mp-row[data-locked="true"] .cy-mp-desc { color: var(--cy-ink3); }
.cyrus-root .cy-mp-ic { display: grid; place-items: center; width: 40px; height: 40px; flex-shrink: 0; border-radius: 12px; background: color-mix(in srgb, rgb(var(--c)) 12%, var(--cy-pop)); box-shadow: inset 0 0 0 1px rgb(var(--c) / 0.35); }
.cyrus-root .cy-mp-name { font-family: var(--font-space), var(--font-inter), sans-serif; font-size: 14.5px; font-weight: 650; color: var(--cy-ink); }
.cyrus-root .cy-mp-tag { font-size: 11px; color: var(--cy-ink3); }
.cyrus-root .cy-mp-desc { margin-top: 2px; display: block; font-size: 12.5px; line-height: 1.4; color: var(--cy-ink2); }
.cyrus-root .cy-mp-cost { margin-top: 7px; display: flex; flex-wrap: wrap; align-items: center; gap: 6px 10px; font-size: 11.5px; color: var(--cy-ink3); }
.cyrus-root .cy-mp-cost b { color: var(--cy-ink); font-weight: 650; font-variant-numeric: tabular-nums; }
.cyrus-root .cy-mp-pick { margin-left: auto; display: grid; place-items: center; width: 20px; height: 20px; border-radius: 50%; color: #fff; background: rgb(var(--c)); font-size: 11px; box-shadow: 0 0 12px rgb(var(--c) / 0.6); }
.cyrus-root .cy-mp-unlock { margin-left: auto; font-size: 11px; font-weight: 650; color: var(--cy-cyan); text-decoration: underline; text-underline-offset: 2px; }

/* Rounded game logos everywhere (GameEmblem): a rounded-square plate with a thin ring; a circle
   inside the branch orbs. "tile" logos (opaque square art, e.g. Rust) fill the plate (cover) on
   their own colour, so no hard corner ever shows; "mark" logos (transparent art) sit inside it. */
.cyrus-root .game-logo-frame {
  position: relative;
  display: inline-grid;
  place-items: center;
  width: 1.25em;
  height: 1.25em;
  border-radius: 28%;
  overflow: hidden;
  vertical-align: middle;
  flex-shrink: 0;
  background: var(--logo-plate, transparent);
}
.cyrus-root .game-logo-frame::after { content: ""; position: absolute; inset: 0; border-radius: inherit; box-shadow: inset 0 0 0 1px rgb(255 255 255 / 0.16); pointer-events: none; }
html[data-theme="light"] .cyrus-root .game-logo-frame::after { box-shadow: inset 0 0 0 1px rgb(22 15 44 / 0.12); }
.cyrus-root .game-logo-frame[data-fit="mark"]::after { box-shadow: none; }
.cyrus-root .game-logo-frame > .game-logo { width: 100%; height: 100%; object-fit: contain; }
.cyrus-root .game-logo-frame[data-fit="tile"] > .game-logo { object-fit: cover; }
.cyrus-root .game-logo-frame[data-fit="tile"][data-inset="true"] > .game-logo { width: 92%; height: 92%; }
.cyrus-root .g-orb .game-logo-frame { width: 64px; height: 64px; margin-top: -16px; border-radius: 50%; }
.cyrus-root .g-orb .game-logo-frame[data-fit="tile"]::after { box-shadow: inset 0 0 0 1.5px rgb(255 255 255 / 0.22), 0 0 0 1px rgb(var(--c) / 0.5); }
.cyrus-root .g-orb .game-logo-frame[data-fit="mark"] { overflow: visible; }
.cyrus-root .g-orb .game-logo-frame .game-logo { width: 100%; height: 100%; margin: 0; }
.cyrus-root .g-orb .game-logo-frame[data-fit="mark"] .game-logo { width: 60px; height: 60px; }

/* The expanded preview panel (store.panelWide): most of the stage, the dock floats over its foot. */
.cyrus-root .cy-panel-wide { box-shadow: var(--panel-shadow), 0 0 0 1px rgb(var(--glow) / 0.12); }
EOF
echo ok

