input.command:
cd /tank/dev-worktrees/cyrus-v6-studio; python3 - <<'EOF'
p="components/cyrus/icons/GameEmblems.tsx"
s=open(p).read()
old=s[s.index("/**\n * A game's mark: its real logo"):]
new='''/**
 * How each owner-supplied logo (public/cyrus/games/) sits in its rounded frame. "tile" = opaque
 * square-ish artwork that is clipped to the frame (cover), on its own `plate` colour so even an
 * inset tile never shows a hard corner; "mark" = transparent artwork that sits inside (contain).
 * Unknown logos default to "mark", which can never show a square edge.
 */
export const LOGO_FIT: Record<string, { fit: "tile" | "mark"; plate?: string; inset?: boolean }> = {
  "/cyrus/games/rust.svg": { fit: "tile", plate: "#cd412b", inset: true },
  "/cyrus/games/palworld.webp": { fit: "tile" },
  "/cyrus/games/valheim.webp": { fit: "tile", plate: "#2b2a2c" },
  "/cyrus/games/minecraft.svg": { fit: "mark" },
  "/cyrus/games/terraria.webp": { fit: "mark" },
  "/cyrus/games/zomboid.png": { fit: "mark" },
};

/**
 * A game's mark: its real logo when it has one (always inside a rounded frame, see LOGO_FIT and
 * .game-logo-frame in studio.css: a circle inside branch orbs, a rounded square elsewhere),
 * otherwise its drawn emblem. Sized in em, like the icons, so it drops in anywhere an emblem did.
 */
export function GameEmblem({
  emblem,
  logo,
  logoTone,
  className = "",
  ...props
}: { emblem: EmblemKey; logo?: string; logoTone?: "light" } & P) {
  if (logo) {
    const f = LOGO_FIT[logo] ?? { fit: "mark" as const };
    return (
      <span className={`game-logo-frame ${className}`} data-fit={f.fit} data-inset={f.inset ? "true" : undefined} style={f.plate ? ({ ["--logo-plate" as string]: f.plate } as React.CSSProperties) : undefined} aria-hidden>
        {/* eslint-disable-next-line @next/next/no-img-element -- tiny static marks; next/image adds nothing here */}
        <img src={logo} alt="" draggable={false} className="game-logo" data-tone={logoTone} />
      </span>
    );
  }
  const Emblem = GAME_EMBLEMS[emblem];
  return <Emblem className={className} {...props} />;
}
'''
s=s.replace(old,new)
s=s.replace('import type { JSX, SVGProps } from "react";','import type { CSSProperties, JSX, SVGProps } from "react";').replace("as React.CSSProperties","as CSSProperties")
open(p,"w").write(s)
EOF
grep -rn "game-logo" components app --include=*.tsx --include=*.css | grep -v "studio.css\|GameEmblems.tsx"

