// Cyrus v6: the Explain tab's plain-English content (pure, client-safe, unit-tested).
//
// Real builds (Minecraft) are explained from what the build service REPORTED (ModBuildResult:
// summary, commands, permissions, config, safety, warnings, errorCode). Template games get a short
// generated explanation from the mod's own description and files, always labelled as a preview:
// nothing there was compiled or tested.
import type { ModBuildView } from "../modbuilder/types";
import type { Game, Mod, ModFile } from "./types";

/* ───────────── Failures (restored from the v4b studio's Explain.tsx) ───────────── */

export type FailInfo = { title: string; tips: string[]; retry: boolean };

const FAIL: Record<string, FailInfo> = {
  compile: { title: "The code didn't compile, even after fixes", tips: ["Ask for fewer features at once. You can add more as changes afterwards.", "Avoid asking for other plugins (like Vault or WorldEdit). Cyrus builds on plain Paper."], retry: true },
  safety: { title: "Blocked by the safety check", tips: ["Remove anything that needs the internet, other programs or files outside the server.", "Webhooks, Discord bots and remote databases can't be built yet."], retry: true },
  refused: { title: "Cyrus won't build this one", tips: ["Cyrus only builds mods that are safe for your players and your server."], retry: false },
  budget: { title: "This mod is bigger than one build", tips: ["Split the idea into two or three smaller mods, or try Yakko for big systems."], retry: true },
  timeout: { title: "This build ran out of time", tips: ["Split the idea into two or three smaller mods."], retry: true },
  cancelled: { title: "You stopped this build", tips: ["Start it again whenever you like."], retry: true },
  ai_unavailable: { title: "Cyrus had a hiccup", tips: ["Trying again in a minute usually works."], retry: true },
  unavailable: { title: "The builder is offline", tips: ["Try again in a few minutes."], retry: true },
  interrupted: { title: "The builder restarted mid-build", tips: ["Nothing is lost. Start it again."], retry: true },
};

export function failInfo(errorCode: string | null | undefined): FailInfo {
  return FAIL[errorCode || ""] ?? { title: "This one didn't build", tips: ["Try again, or describe it a little differently."], retry: true };
}

/** "Everyone" / "Operators" / "Nobody by default" for a permission's default. */
export function permissionWho(def: string): string {
  const d = (def || "").toLowerCase();
  if (d === "true") return "Everyone";
  if (d === "false") return "Nobody by default";
  if (d === "not op" || d === "!op") return "Everyone but operators";
  return "Operators";
}

/** The four guarantees the compiled-code scan checks for every real build. */
export function safetyChecks(pluginName: string | null): [string, string][] {
  return [
    ["No internet access", "It can't send your data anywhere."],
    ["Can't run programs", "Nothing outside the game gets started."],
    ["Only its own folder", `Reads and writes only plugins/${pluginName || "its own folder"}.`],
    ["No hidden admin access", "No secret players with special powers."],
  ];
}

export type SafetySummary = { verdict: "pass" | "warn" | "block" | "unknown"; label: string; notes: string[] };

export function safetySummary(b: Pick<ModBuildView, "result">): SafetySummary {
  const sf = b.result?.safety;
  if (!sf) return { verdict: "unknown", label: "Not scanned", notes: [] };
  const notes = [...new Set(sf.findings.filter((f) => f.severity === "warn").map((f) => f.message))];
  if (sf.verdict === "block") return { verdict: "block", label: "Blocked", notes: [...new Set(sf.findings.map((f) => f.message))] };
  return { verdict: notes.length ? "warn" : "pass", label: notes.length ? "Passed with notes" : "Passed", notes };
}

/** What a retry re-sends: a change to a version builds on it again; a fresh build starts over. */
export function retryRequest(b: Pick<ModBuildView, "prompt" | "changeRequest" | "baseBuildId" | "mcVersion">): { text: string; change: boolean; mcVersion: string } {
  return b.baseBuildId && b.changeRequest ? { text: b.changeRequest, change: true, mcVersion: b.mcVersion } : { text: b.prompt, change: false, mcVersion: b.mcVersion };
}

/* ───────────── Template previews ───────────── */

export type FileRole = { path: string; role: string };

/** A one-line role for a generated file, from its path (template previews). */
export function fileRole(path: string): string {
  const p = path.toLowerCase();
  const base = p.split("/").pop() ?? p;
  if (/^readme|\.md$/.test(base)) return base.startsWith("changelog") ? "What changed, version by version" : "Read-me: what it does and how to set it up";
  if (/(^|\/)(tests?|spec)\/|_spec\.|\.test\./.test(p)) return "Tests for the mod's logic";
  if (/translate|translations|\/lang\//.test(p)) return "Text the players see (translations)";
  if (/sandbox|config|settings|\.cfg$/.test(p)) return "Settings a server owner can change";
  if (/mod\.info|plugin\.yml|manifest\.json|\.csproj$|\.toml$|build\.txt|description\.txt|enabled\.txt/.test(p)) return "Mod details the game's loader reads (name, version, load order)";
  if (/hud|ui|journal|overlay|menu/.test(p)) return "On-screen interface";
  if (/server/.test(p) && /\.(lua|cs|java)$/.test(p)) return "Server-side logic";
  if (/client/.test(p) && /\.(lua|cs|java)$/.test(p)) return "Client-side logic (runs on the player's game)";
  if (/items?_|recipes?_|vehicles?\//.test(p)) return "Game data: items, recipes or vehicles";
  if (/sounds?_|\.ogg$|\.wav$/.test(p)) return "Sound definitions";
  if (/map\.info|spawnpoints|\/maps\//.test(p)) return "Map data";
  if (/shader|\.glsl$|\.fsh$|\.vsh$/.test(p)) return "Visual shader";
  if (/\.(lua|cs|java)$/.test(p)) return "Mod logic";
  if (/\.(json|xml|txt)$/.test(p)) return "Data the mod loads";
  return "Supporting file";
}

export type TemplateExplain = { lead: string; points: string[]; files: FileRole[]; toolchain: string; note: string };

/** The short generated explanation for a template-game mod (labelled "Template preview" in the UI). */
export function templateExplain(mod: Pick<Mod, "name" | "summary" | "tags">, game: Pick<Game, "name" | "toolchain">, files: Pick<ModFile, "path">[]): TemplateExplain {
  const files2 = files.map((f) => ({ path: f.path, role: fileRole(f.path) }));
  const roles = new Set(files2.map((f) => f.role));
  const points: string[] = [];
  if (roles.has("Settings a server owner can change")) points.push("Its numbers live in a settings file, so they can be tuned without touching the code.");
  if (roles.has("Server-side logic") && roles.has("Client-side logic (runs on the player's game)")) points.push("It has a server part and a client part: in a real install, players would need the client part too.");
  else if (roles.has("Client-side logic (runs on the player's game)")) points.push("Part of it runs on the player's own game.");
  if (roles.has("On-screen interface")) points.push("It adds something players see on screen.");
  if (roles.has("Text the players see (translations)")) points.push("Its player-facing text is kept in a translation file.");
  if (roles.has("Tests for the mod's logic")) points.push("It comes with tests for its logic.");
  if (mod.tags.length) points.push(`Tagged: ${mod.tags.slice(0, 4).join(", ")}.`);
  return {
    lead: mod.summary || `${mod.name} for ${game.name}.`,
    points,
    files: files2,
    toolchain: game.toolchain,
    note: `Cyrus wrote this from its ${game.name} template. It has not been compiled, installed or tested in the game, so treat it as a starting point, not a finished mod.`,
  };
}

