"use client";

// v6 Explain tab (owner: "Cyrus still needs to have the explain tab alongside notes, code, files,
// and versions"). The v4b studio's "Explain this mod" restored for the v5 panel: everything a real
// build reported, in plain English (what it does, how to use it, commands, settings, permissions,
// the safety scan, limits), the request and the images Cyrus looked at, and for a failed build why
// and the two ways forward. Template-game mods get a short generated explanation, labelled.
import type { ReactNode } from "react";
import { BuiltWithCyrusBadge } from "@/components/cyrus/brand/BuiltWithCyrusBadge";
import { CyrusAvatar } from "@/components/cyrus/brand/CyrusBrand";
import { ModelGlyph } from "@/components/cyrus/icons/ModelGlyphs";
import { CheckIcon, CodeIcon, EditIcon, FileIcon, RestoreIcon } from "@/components/cyrus/icons/ui";
import { isTerminal, type ModBuildView } from "@/lib/modbuilder/types";
import { failInfo, permissionWho, safetyChecks, safetySummary, templateExplain } from "@/lib/cyrus/explain";
import { MODEL_BY_ID } from "@/lib/cyrus/data";
import { viewMeta } from "@/lib/cyrus/projects";
import type { Game, Mod, ModFile, ModVersion } from "@/lib/cyrus/types";

function Section({ title, count, sub, children }: { title: string; count?: number; sub?: ReactNode; children: ReactNode }) {
  return (
    <section className="border-t border-cy-line pt-4">
      <h4 className="flex items-center gap-2 font-cy-display text-[13.5px] font-semibold text-cy-ink">
        {title}
        {count !== undefined && <span className="rounded-md bg-[rgb(var(--glow)/0.1)] px-1.5 text-[10.5px] tabular-nums text-cy-muted">{count}</span>}
      </h4>
      {sub && <p className="mt-0.5 text-[11.5px] text-cy-muted">{sub}</p>}
      <div className="mt-2.5">{children}</div>
    </section>
  );
}

function Rows({ children }: { children: ReactNode }) {
  return <div className="divide-y divide-cy-line overflow-hidden rounded-xl border border-cy-line">{children}</div>;
}

function Row({ k, v, who, mono = true }: { k: string; v: string; who?: string; mono?: boolean }) {
  return (
    <div className="grid grid-cols-1 gap-x-3 gap-y-1 px-3 py-2.5 sm:grid-cols-[minmax(0,40%)_minmax(0,1fr)_auto] sm:items-baseline">
      <code className={`min-w-0 break-words text-[12px] text-cy-accent-ink ${mono ? "font-mono" : ""}`}>{k}</code>
      <span className="min-w-0 text-[12.5px] leading-snug text-cy-ink-2">{v}</span>
      {who && <span className="justify-self-start whitespace-nowrap rounded-full bg-[rgb(var(--glow)/0.1)] px-2 py-0.5 text-[10.5px] font-medium text-cy-muted sm:justify-self-end">{who}</span>}
    </div>
  );
}

function Request({ b }: { b: ModBuildView }) {
  const meta = viewMeta(b);
  const atts = meta.attachments ?? [];
  return (
    <Section title={b.changeRequest ? "The change you asked for" : "What you asked for"}>
      <blockquote className="rounded-xl border-l-2 border-cy-accent bg-[rgb(var(--glow)/0.05)] px-3.5 py-2.5 text-[12.5px] leading-relaxed text-cy-ink-2">{b.changeRequest || b.prompt}</blockquote>
      {b.changeRequest && (
        <details className="mt-2 text-[12px] text-cy-muted">
          <summary className="cursor-pointer select-none hover:text-cy-ink">Original description</summary>
          <p className="mt-1.5 leading-relaxed text-cy-ink-2">{b.prompt}</p>
        </details>
      )}
      {atts.length > 0 && (
        <div className="mt-3">
          <div className="flex flex-wrap gap-2">
            {atts.map((a) => (
              <a key={a.n} href={`/api/mod-builder/builds/${b.id}/attachments/${a.n}`} target="_blank" rel="noreferrer" title={a.name} className="block h-16 w-16 overflow-hidden rounded-xl border border-cy-line-2">
                {/* eslint-disable-next-line @next/next/no-img-element */}
                <img src={`/api/mod-builder/builds/${b.id}/attachments/${a.n}`} alt={a.name} loading="lazy" className="h-full w-full object-cover" />
              </a>
            ))}
          </div>
          <p className="mt-1.5 text-[11.5px] text-cy-muted">{atts.length === 1 ? "Cyrus looked at this image" : `Cyrus looked at these ${atts.length} images`} while planning.</p>
        </div>
      )}
    </Section>
  );
}

function Safety({ b }: { b: ModBuildView }) {
  const s = safetySummary(b);
  const tone = s.verdict === "pass" ? "bg-emerald-500/12 text-emerald-500" : s.verdict === "warn" ? "bg-amber-500/12 text-amber-500" : s.verdict === "block" ? "bg-rose-500/12 text-rose-400" : "bg-[rgb(var(--glow)/0.1)] text-cy-muted";
  return (
    <Section title="Safety check">
      <div className="mb-2.5 flex items-center gap-2">
        <span className={`inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 text-[11px] font-semibold ${tone}`}>
          <span className="h-1.5 w-1.5 rounded-full bg-current" /> {s.label}
        </span>
      </div>
      {s.verdict !== "block" && (
        <ul className="space-y-1.5">
          {safetyChecks(b.pluginName).map(([t, d]) => (
            <li key={t} className="flex items-start gap-2 text-[12.5px] text-cy-ink-2">
              <CheckIcon className="mt-[3px] shrink-0 text-emerald-500" />
              <span>
                <b className="font-semibold text-cy-ink">{t}.</b> {d}
              </span>
            </li>
          ))}
        </ul>
      )}
      {s.notes.length > 0 && <p className="mt-2.5 rounded-lg bg-amber-500/8 px-3 py-2 text-[12px] leading-relaxed text-cy-ink-2">This mod {s.notes.join("; ")}. That&apos;s allowed, just worth knowing.</p>}
      <p className="mt-2 text-[11px] text-cy-faint">An automated scan of the compiled code. It checks for risky behaviour; it doesn&apos;t promise the mod is bug-free.</p>
    </Section>
  );
}

function Failure({ b, onRetry, onEdit }: { b: ModBuildView; onRetry?: () => void; onEdit?: () => void }) {
  const f = failInfo(b.errorCode);
  const stopped = b.errorCode === "cancelled";
  return (
    <section className="rounded-2xl border border-rose-500/30 bg-rose-500/[0.06] p-4">
      <div className="text-[10.5px] font-semibold uppercase tracking-[0.16em] text-rose-400">{stopped ? "Stopped" : "Why it didn't build"}</div>
      <h3 className="mt-1 font-cy-display text-[16px] font-semibold text-cy-ink">{f.title}</h3>
      {b.error && <p className="mt-1.5 text-[12.5px] leading-relaxed text-cy-ink-2">{b.error}</p>}
      <ul className="mt-2 list-disc space-y-1 pl-4 text-[12.5px] text-cy-ink-2">
        {f.tips.map((t) => (
          <li key={t}>{t}</li>
        ))}
      </ul>
      {b.result?.errorDetail && b.errorCode === "compile" && (
        <details className="mt-2.5 text-[12px] text-cy-muted">
          <summary className="cursor-pointer select-none hover:text-cy-ink">What the compiler said</summary>
          <pre className="mt-1.5 max-h-56 overflow-auto rounded-lg bg-[var(--code-bg)] p-2.5 font-mono text-[11px] leading-relaxed text-cy-ink-2">{b.result.errorDetail}</pre>
        </details>
      )}
      <p className="mt-2 text-[11.5px] text-cy-muted">Tokens it held went back to you.</p>
      {(onRetry || onEdit) && (
        <div className="mt-3 flex flex-wrap gap-2">
          {f.retry && onRetry && (
            <button type="button" onClick={onRetry} className="inline-flex h-8 items-center gap-1.5 rounded-lg px-3 text-[12px] font-semibold text-white transition hover:brightness-110" style={{ background: "linear-gradient(135deg, #8b5cf6, #6366f1 45%, #06b6d4)" }}>
              <RestoreIcon /> Try again
            </button>
          )}
          {onEdit && (
            <button type="button" onClick={onEdit} className="cy5-btn-ghost inline-flex h-8 items-center gap-1.5 border border-cy-line-2 px-3 text-[12px] font-medium">
              <EditIcon /> {f.retry ? "Edit and retry" : "Describe something else"}
            </button>
          )}
        </div>
      )}
    </section>
  );
}

function RealExplain({ b, version, onRetry, onEdit }: { b: ModBuildView; version: ModVersion; onRetry?: () => void; onEdit?: () => void }) {
  if (b.status === "failed")
    return (
      <>
        <Failure b={b} onRetry={onRetry} onEdit={onEdit} />
        <Request b={b} />
      </>
    );
  if (!isTerminal(b.status))
    return (
      <>
        <p className="shimmer-text text-[13px]">Cyrus is writing, compiling and safety-checking this version. Its explanation appears here when it&apos;s ready.</p>
        <Request b={b} />
      </>
    );
  const r = b.result;
  const s = r?.summary;
  const m = MODEL_BY_ID[version.model];
  const secs = Math.max(1, Math.round((b.durationMs ?? 0) / 1000));
  return (
    <>
      <section>
        <div className="flex items-center gap-2 text-[10.5px] font-semibold uppercase tracking-[0.16em] text-cy-muted">
          <CyrusAvatar size={20} /> In plain English
        </div>
        <h3 className="mt-2 font-cy-display text-[17px] font-semibold leading-snug text-cy-ink">{s?.tagline || `${b.pluginName || "Your plugin"} is built`}</h3>
        {s?.text && <p className="mt-1.5 text-[13px] leading-relaxed text-cy-ink-2">{s.text}</p>}
        {s?.changes && b.changeRequest && (
          <p className="mt-2 rounded-lg bg-[rgb(var(--glow)/0.06)] px-3 py-2 text-[12.5px] leading-relaxed text-cy-ink-2">
            <b className="text-cy-ink">What changed.</b> {s.changes}
          </p>
        )}
      </section>

      {!!s?.howToUse?.length && (
        <Section title="How to use it">
          <ol className="space-y-2">
            {s.howToUse.map((h, i) => (
              <li key={i} className="flex gap-2.5 text-[12.5px] leading-relaxed text-cy-ink-2">
                <span className="grid h-5 w-5 shrink-0 place-items-center rounded-full bg-[rgb(var(--glow)/0.14)] text-[10.5px] font-semibold text-cy-accent-ink">{i + 1}</span>
                <span>{h}</span>
              </li>
            ))}
          </ol>
        </Section>
      )}

      {!!r?.commands?.length && (
        <Section title="Commands" count={r.commands.length}>
          <Rows>
            {r.commands.map((c, i) => (
              <Row key={i} k={c.usage} v={c.description} who={c.whoCanUse || (c.permission ? "With permission" : "Everyone")} />
            ))}
          </Rows>
        </Section>
      )}

      {!!r?.config?.length && (
        <Section title="Settings you can change" count={r.config.length} sub={<>In <code className="font-mono text-cy-ink-2">plugins/{b.pluginName}/config.yml</code> on your server.</>}>
          <Rows>
            {r.config.map((c, i) => (
              <Row key={i} k={c.key} v={c.description} who={c.default ? `Default ${c.default}` : undefined} />
            ))}
          </Rows>
        </Section>
      )}

      {!!r?.permissions?.length && (
        <Section title="Who can do what" count={r.permissions.length} sub="Works with LuckPerms or any permissions plugin.">
          <Rows>
            {r.permissions.map((p, i) => (
              <Row key={i} k={p.node} v={p.description} who={permissionWho(p.default)} />
            ))}
          </Rows>
        </Section>
      )}

      <Safety b={b} />

      {(!!s?.limitations?.length || !!r?.warnings?.length) && (
        <Section title="Good to know">
          <ul className="list-disc space-y-1 pl-4 text-[12.5px] leading-relaxed text-cy-ink-2">
            {(s?.limitations ?? []).map((l, i) => (
              <li key={`l${i}`}>{l}</li>
            ))}
            {(r?.warnings ?? []).slice(0, 6).map((w, i) => (
              <li key={`w${i}`}>{w}</li>
            ))}
          </ul>
        </Section>
      )}

      <Request b={b} />

      <section className="flex flex-wrap items-center gap-3 border-t border-cy-line pt-4">
        <BuiltWithCyrusBadge variant="generic" height={30} />
        <span className="flex items-center gap-1.5 text-[11.5px] text-cy-muted">
          <ModelGlyph id={version.model} size={14} /> {m.name} · Paper {b.mcVersion} · built in {secs}s · {b.attempts > 1 ? `fixed itself ${b.attempts - 1}×` : "first try"}
        </span>
      </section>
    </>
  );
}

function TemplateExplainView({ mod, game, files, version, onOpen }: { mod: Mod; game: Pick<Game, "name" | "toolchain">; files: ModFile[]; version?: ModVersion; onOpen: (path: string) => void }) {
  const e = templateExplain(mod, game, files);
  return (
    <>
      <section>
        <div className="flex flex-wrap items-center gap-2">
          <span className="inline-flex items-center gap-1.5 text-[10.5px] font-semibold uppercase tracking-[0.16em] text-cy-muted">
            <CyrusAvatar size={20} /> In plain English
          </span>
          <span className="rounded-full bg-amber-500/12 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wider text-amber-500">Template preview</span>
        </div>
        <h3 className="mt-2 font-cy-display text-[17px] font-semibold leading-snug text-cy-ink">{mod.name}</h3>
        <p className="mt-1.5 text-[13px] leading-relaxed text-cy-ink-2">{e.lead}</p>
        {e.points.length > 0 && (
          <ul className="mt-2 list-disc space-y-1 pl-4 text-[12.5px] leading-relaxed text-cy-ink-2">
            {e.points.map((p) => (
              <li key={p}>{p}</li>
            ))}
          </ul>
        )}
      </section>
      {e.files.length > 0 && (
        <Section title="What's in it" count={e.files.length} sub={e.toolchain}>
          <Rows>
            {e.files.map((f) => (
              <button key={f.path} type="button" onClick={() => onOpen(f.path)} className="flex w-full items-center gap-2.5 px-3 py-2 text-left transition hover:bg-[rgb(var(--glow)/0.06)]">
                <FileIcon className="shrink-0 text-cy-muted" />
                <span className="min-w-0 flex-1">
                  <span className="block truncate font-mono text-[11.5px] text-cy-ink">{f.path}</span>
                  <span className="block text-[11.5px] text-cy-muted">{f.role}</span>
                </span>
                <CodeIcon className="shrink-0 text-cy-faint" />
              </button>
            ))}
          </Rows>
        </Section>
      )}
      {version?.prompt && (
        <Section title="What you asked for">
          <blockquote className="rounded-xl border-l-2 border-cy-accent bg-[rgb(var(--glow)/0.05)] px-3.5 py-2.5 text-[12.5px] leading-relaxed text-cy-ink-2">{version.prompt}</blockquote>
        </Section>
      )}
      <p className="rounded-xl border border-dashed border-cy-line-2 px-3.5 py-2.5 text-[12px] leading-relaxed text-cy-muted">{e.note}</p>
    </>
  );
}

export function ExplainTab({
  mod,
  game,
  version,
  build,
  files,
  streaming,
  onOpen,
  onRetry,
  onEdit,
}: {
  mod: Mod;
  game: Pick<Game, "name" | "toolchain">;
  version?: ModVersion;
  build?: ModBuildView;
  files: ModFile[];
  streaming: boolean;
  onOpen: (path: string) => void;
  onRetry?: () => void;
  onEdit?: () => void;
}) {
  return (
    <div className="min-h-0 flex-1 space-y-4 overflow-y-auto px-5 py-4">
      {streaming ? (
        <p className="shimmer-text text-[13px]">Cyrus is forging this version. Its explanation appears here when it&apos;s done.</p>
      ) : mod.idea ? (
        <p className="text-[13px] leading-relaxed text-cy-ink-2">This is a starter idea, not a built mod yet. Click it on the network to write its prompt, then forge it.</p>
      ) : version?.real && build ? (
        <RealExplain b={build} version={version} onRetry={onRetry} onEdit={onEdit} />
      ) : version?.real ? (
        <p className="text-[13px] text-cy-muted">Loading this version…</p>
      ) : version ? (
        <TemplateExplainView mod={mod} game={game} files={files} version={version} onOpen={onOpen} />
      ) : (
        <p className="text-[13px] text-cy-muted">Nothing to explain yet. Forge a version first.</p>
      )}
    </div>
  );
}

