export function IconBase({ children, ...props }: IconProps) {
  const labelled = props["aria-label"] != null || props["aria-labelledby"] != null;
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox="0 0 24 24"
      width="1em"
      height="1em"
      fill="none"
      stroke="currentColor"
      strokeWidth={1.6}
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden={labelled ? undefined : true}
      focusable="false"
      {...props}
    >
      {children}
    </svg>
  );
}

/** UI chrome icons run a touch heavier so they stay crisp at 14–16px. */
function UiBase(props: IconProps) {
  return <IconBase strokeWidth={1.7} {...props} />;
}

