"use client";

// v6 (restored from v4b): "Try again" and "Edit and retry" for a real build that didn't build.
// A failed CHANGE is asked again on the same mod (it builds on the last version that worked); a
// failed FIRST build starts the mod over from its original description in the same category.
import type { ModBuildView } from "../modbuilder/types";
import { retryRequest } from "./explain";
import { forge } from "./forge";
import { realModId } from "./real";
import { findMod, isJobLive, useStore } from "./store";

function place(b: ModBuildView, change: boolean) {
  const s = useStore.getState();
  const mod = findMod(realModId(b.rootBuildId ?? b.id));
  if (change && mod) s.select({ level: "mod", gameId: mod.gameId, category: mod.category, modId: mod.id }, { openPanel: true });
  else s.select({ level: "category", gameId: mod?.gameId ?? "minecraft", category: mod?.category ?? "mechanics" }, { openPanel: false });
}

export function retryBuild(b: ModBuildView) {
  const s = useStore.getState();
  if (isJobLive(s.job)) {
    s.toast({ tone: "info", title: "Cyrus is busy", body: "Wait for the running forge to finish, then try again." });
    return;
  }
  const req = retryRequest(b);
  s.setMcVersion(req.mcVersion);
  place(b, req.change);
  void forge(req.text);
}

export function editAndRetry(b: ModBuildView) {
  const req = retryRequest(b);
  useStore.getState().setMcVersion(req.mcVersion);
  place(b, req.change);
  useStore.setState((st) => ({ prefill: { text: req.text, tick: (st.prefill?.tick ?? 0) + 1 } }));
}
