    const sb = mb.has(p) ? mb.get(p)! : null;
    const kind = sa === null ? "added" : sb === null ? "removed" : sa === sb ? "same" : "changed";
    return { path: p, kind, sizeA: sa, sizeB: sb };
  });
}
