"use client";

// v6 (restored from v4b DiffView): compare two versions of a mod, file by file, unified diff with
// collapsed unchanged runs. Real versions load their source from the build service on demand.
import { useEffect, useMemo, useState } from "react";
import { CloseIcon, CompareIcon } from "@/components/cyrus/icons/ui";
import { diffLines, diffStats, hunks, type DiffOp } from "@/lib/cyrus/diff";
import { useStore } from "@/lib/cyrus/store";
import type { ModFile, ModVersion } from "@/lib/cyrus/types";

type Row = { path: string; kind: "added" | "removed" | "changed" | "same"; ops: DiffOp[]; added: number; removed: number };

function useFiles(v: ModVersion): ModFile[] | "loading" | "error" {
  const loadRealFiles = useStore((s) => s.loadRealFiles);
  const state = useStore((s) => (v.real ? s.realFiles[v.real.buildId] : undefined));
  useEffect(() => {
    if (v.real && v.real.paths.length) void loadRealFiles(v.real.buildId, v.real.paths.map((p) => p.path));
  }, [v, loadRealFiles]);
  if (!v.real) return v.files;
  if (state === "error") return "error";
  return Array.isArray(state) ? state : v.real.paths.length ? "loading" : [];
}

export function compareRows(a: ModFile[], b: ModFile[]): Row[] {
  const ma = new Map(a.map((f) => [f.path, f.content]));
  const mb = new Map(b.map((f) => [f.path, f.content]));
  const paths = [...new Set([...ma.keys(), ...mb.keys()])].sort();
  return paths.map((path) => {
    const ops = diffLines(ma.get(path) ?? "", mb.get(path) ?? "");
    const st = diffStats(ops);
    const kind: Row["kind"] = !ma.has(path) ? "added" : !mb.has(path) ? "removed" : st.added + st.removed ? "changed" : "same";
    return { path, kind, ops, ...st };
  });
}

export function CompareView({ from, to, onClose }: { from: ModVersion; to: ModVersion; onClose: () => void }) {
  const fa = useFiles(from);
  const fb = useFiles(to);
  const ready = Array.isArray(fa) && Array.isArray(fb);
  const rows = useMemo(() => (Array.isArray(fa) && Array.isArray(fb) ? compareRows(fa, fb) : null), [fa, fb]);
  const [sel, setSel] = useState<string | null>(null);
  const [showSame, setShowSame] = useState(false);
  const changed = rows?.filter((r) => r.kind !== "same") ?? [];
  const cur = rows?.find((r) => r.path === sel) ?? changed[0] ?? rows?.[0];
  const totals = changed.reduce((t, r) => ({ added: t.added + r.added, removed: t.removed + r.removed }), { added: 0, removed: 0 });
  const list = (rows ?? []).filter((r) => showSame || r.kind !== "same");

  return (
    <div className="flex min-h-0 flex-1 flex-col">
      <div className="flex flex-wrap items-center gap-2 border-b border-cy-line px-4 py-2.5 text-[12px]">
        <CompareIcon className="text-cy-accent" />
        <span className="font-cy-display font-semibold text-cy-ink">
          {from.label} → {to.label}
        </span>
        {rows && (
          <span className="text-cy-muted">
            {changed.length} file{changed.length === 1 ? "" : "s"} changed <b className="font-mono text-emerald-500">+{totals.added}</b> <b className="font-mono text-rose-400">−{totals.removed}</b>
          </span>
        )}
        <button type="button" onClick={onClose} className="cy5-btn-ghost ml-auto inline-flex h-7 items-center gap-1 px-2 text-[11.5px]">
          <CloseIcon /> Close compare
        </button>
      </div>
      {fa === "error" || fb === "error" ? (
        <div className="grid flex-1 place-items-center p-8 text-[13px] text-cy-muted">The builder didn&apos;t answer. Try again in a moment.</div>
      ) : !ready || !rows ? (
        <div className="grid flex-1 place-items-center p-8 text-[13px]">
          <span className="shimmer-text">Comparing every file…</span>
        </div>
      ) : (
        <>
          <div className="flex gap-1 overflow-x-auto border-b border-cy-line px-3 py-2" style={{ scrollbarWidth: "none" }}>
            {list.map((r) => (
              <button
                key={r.path}
                type="button"
                onClick={() => setSel(r.path)}
                title={r.path}
                className={`flex shrink-0 items-center gap-1.5 rounded-lg px-2 py-1 font-mono text-[11px] transition ${cur?.path === r.path ? "bg-[rgb(var(--glow)/0.14)] text-cy-ink" : "text-cy-muted hover:text-cy-ink"}`}
              >
                <span className={`font-semibold ${r.kind === "added" ? "text-emerald-500" : r.kind === "removed" ? "text-rose-400" : r.kind === "changed" ? "text-amber-500" : "text-cy-faint"}`}>{r.kind === "added" ? "A" : r.kind === "removed" ? "D" : r.kind === "changed" ? "M" : "="}</span>
                {r.path.split("/").pop()}
              </button>
            ))}
            {rows.some((r) => r.kind === "same") && (
              <button type="button" onClick={() => setShowSame((v) => !v)} className="shrink-0 px-2 text-[11px] text-cy-faint hover:text-cy-ink">
                {showSame ? "Hide" : "Show"} {rows.filter((r) => r.kind === "same").length} unchanged
              </button>
            )}
          </div>
          <div className="code min-h-0 flex-1 overflow-auto py-2 font-mono text-[12px] leading-[1.6]">
            {!changed.length && <p className="px-4 py-6 text-center font-sans text-[13px] text-cy-muted">These two versions have identical source.</p>}
            {cur && <Hunks ops={cur.ops} />}
          </div>
        </>
      )}
    </div>
  );
}

function Hunks({ ops }: { ops: DiffOp[] }) {
  const hs = useMemo(() => hunks(ops, 3), [ops]);
  if (!hs.length || ops.every((o) => o.t === "eq")) return <p className="px-4 py-6 text-center font-sans text-[13px] text-cy-muted">No changes in this file.</p>;
  return (
    <table className="w-full border-collapse">
      <tbody>
        {hs.map((h, hi) => (
          <HunkRows key={hi} ops={h.ops} skipped={h.skippedBefore} />
        ))}
      </tbody>
    </table>
  );
}

function HunkRows({ ops, skipped }: { ops: DiffOp[]; skipped: number }) {
  return (
    <>
      {skipped > 0 && (
        <tr>
          <td colSpan={3} className="bg-[rgb(var(--glow)/0.05)] px-4 py-1 font-sans text-[11px] text-cy-faint">
            ⋯ {skipped} unchanged line{skipped === 1 ? "" : "s"}
          </td>
        </tr>
      )}
      {ops.map((o, i) => (
        <tr key={i} className={o.t === "add" ? "bg-emerald-500/10" : o.t === "del" ? "bg-rose-500/10" : undefined}>
          <td className="w-9 select-none pr-1 text-right align-top text-[10.5px] text-cy-faint">{o.a ?? ""}</td>
          <td className="w-9 select-none pr-2 text-right align-top text-[10.5px] text-cy-faint">{o.b ?? ""}</td>
          <td className="whitespace-pre-wrap break-all pr-4 align-top text-cy-ink-2">
            <span className={`mr-2 select-none ${o.t === "add" ? "text-emerald-500" : o.t === "del" ? "text-rose-400" : "text-cy-faint"}`}>{o.t === "add" ? "+" : o.t === "del" ? "−" : " "}</span>
            {o.text}
          </td>
        </tr>
      ))}
    </>
  );
}

