/** The mod's title, renamable in place (real projects save to the DB; template mods locally). */
function ModTitle({ mod }: { mod: NonNullable<ReturnType<typeof useMod>> }) {
  const [editing, setEditing] = useState(false);
  const [draft, setDraft] = useState(mod.name);
  const ref = useRef<HTMLInputElement>(null);
  const patchProject = useStore((s) => s.patchProject);
  const toast = useStore((s) => s.toast);
  useEffect(() => setDraft(mod.name), [mod.name]);
  useEffect(() => {
    if (editing) ref.current?.select();
  }, [editing]);
  const canRename = !mod.seed && !mod.idea;
  const save = async () => {
    setEditing(false);
    const t = draft.trim().slice(0, CYRUS_TITLE_MAX);
    if (!t || t === mod.name) return setDraft(mod.name);
    if (mod.real) {
      const e = await patchProject(mod.real.rootId, { title: t });
      if (e) toast({ tone: "error", title: "Couldn't rename", body: e });
    } else useStore.setState((s) => ({ userMods: s.userMods.map((m) => (m.id === mod.id ? { ...m, name: t } : m)) }));
  };
  if (editing)
    return (
      <input
        ref={ref}
        value={draft}
        maxLength={CYRUS_TITLE_MAX}
        onChange={(e) => setDraft(e.target.value)}
        onBlur={() => void save()}
        onKeyDown={(e) => {
          if (e.key === "Enter") void save();
          if (e.key === "Escape") {
            e.stopPropagation();
            setDraft(mod.name);
            setEditing(false);
          }
        }}
        aria-label="Mod name"
        className="w-full rounded-lg border border-cy-line-2 bg-[rgb(var(--glow)/0.06)] px-2 py-0.5 font-cy-display text-[18px] font-semibold leading-tight text-cy-ink outline-none focus:border-cy-accent"
      />
    );
  return (
    <h2 className="group flex min-w-0 items-center gap-1.5 font-cy-display text-[19px] font-semibold leading-tight text-cy-ink">
      <span className="truncate" onDoubleClick={() => canRename && setEditing(true)}>
        {mod.name}
      </span>
      {canRename && (
        <button type="button" onClick={() => setEditing(true)} className="shrink-0 text-[13px] text-cy-faint opacity-60 transition hover:text-cy-ink group-hover:opacity-100" aria-label="Rename" title="Rename">
          <EditIcon />
        </button>
      )}
    </h2>
  );
}

/** Favourite + copy link, for real projects (both were in the v4b studio). */
function ProjectActions({ mod, buildId }: { mod: NonNullable<ReturnType<typeof useMod>>; buildId?: string }) {
  const patchProject = useStore((s) => s.patchProject);
  const toast = useStore((s) => s.toast);
  const [copied, setCopied] = useState(false);
  const fav = !!mod.real?.favourite;
  return (
    <>
      <button
        type="button"
        onClick={async () => {
          const e = await patchProject(mod.real!.rootId, { favourite: !fav });
          if (e) toast({ tone: "error", title: "Couldn't save", body: e });
        }}
        className={`cy5-btn-ghost h-9 w-9 ${fav ? "text-amber-400" : "text-cy-muted"}`}
        aria-label={fav ? "Remove from favourites" : "Add to favourites"}
        aria-pressed={fav}
        title={fav ? "Favourite" : "Add to favourites"}
      >
        <StarIcon fill={fav ? "currentColor" : "none"} />
      </button>
      {buildId && (
        <button
          type="button"
          onClick={() => {
            const url = `${window.location.origin}/dashboard/cyrus/${buildId}`;
            void navigator.clipboard?.writeText(url).then(
              () => {
                setCopied(true);
                window.setTimeout(() => setCopied(false), 1600);
