/* ===========================================================================
   Featured rail entry (NavItem.highlight; today: Cyrus). Added 2026-10-08.
   A quiet violet wash from the left edge, a short gradient underline under
   the label and a lit icon, so the entry reads as special without shouting.
   Unlayered on purpose: it sits on top of the rail's own rest/hover/active
   rules (in @layer components above) without !important. Light mode trades
   the glow for a deeper ink + tint, since glow on white reads as blur.
   =========================================================================== */
.nx-navlink.nx-navlink-feature {
  background: linear-gradient(90deg, rgba(140, 58, 233, .16), rgba(95, 208, 255, .05) 62%, transparent 92%);
  border-color: rgba(167, 139, 250, .2);
}
.nx-navlink.nx-navlink-feature::after {
  content: ""; position: absolute; left: 12px; bottom: 4px; width: 46px; max-width: 45%; height: 1.5px; border-radius: 2px; pointer-events: none;
  background: linear-gradient(90deg, #a78bfa, #67e8f9 70%, transparent);
  box-shadow: 0 0 8px rgba(167, 139, 250, .55);
  opacity: .8;
}
.nx-navlink.nx-navlink-feature .nx-ico { color: #c4b5fd; filter: drop-shadow(0 0 3px rgba(167, 139, 250, .75)) drop-shadow(0 0 9px rgba(103, 232, 249, .3)); }
.nx-navlink.nx-navlink-feature:not(.nx-navlink-on) { color: #d9d0ff; }
.nx-navlink.nx-navlink-feature.nx-navlink-on { border-color: rgba(167, 139, 250, .38); }
/* compact rail (icon only): the underline becomes a dot under the icon */
.nx-navlink.nx-navlink-feature.w-10::after { left: 50%; width: 14px; margin-left: -7px; bottom: 3px; }
html[data-theme="light"] .nx-navlink.nx-navlink-feature {
  background: linear-gradient(90deg, rgba(124, 58, 237, .10), rgba(8, 145, 178, .04) 62%, transparent 92%);
  border-color: rgba(124, 58, 237, .18);
}
html[data-theme="light"] .nx-navlink.nx-navlink-feature::after { background: linear-gradient(90deg, #7c3aed, #0891b2 70%, transparent); box-shadow: none; opacity: .9; }
html[data-theme="light"] .nx-navlink.nx-navlink-feature .nx-ico { color: #6d28d9; filter: none; }
html[data-theme="light"] .nx-navlink.nx-navlink-feature:not(.nx-navlink-on) { color: #4c1d95; }
@media (prefers-reduced-motion: no-preference) {
  .nx-navlink.nx-navlink-feature::after { transition: width .25s ease, opacity .25s ease; }
  .nx-navlink.nx-navlink-feature:hover::after { width: 64px; opacity: 1; }
}
EOF
