describe("cyrus v6 plan estimates (from the live cost table)", () => {
  it("counts are [tokens / high, tokens / typical], rounded down", () => {
    assert.deepEqual(countRange(750, [30, 70]), [10, 25]);
    assert.deepEqual(countRange(3500, [60, 220]), [15, 55]);
    assert.equal(niceDown(19.9), 19);
    assert.equal(niceDown(57), 55);
    assert.equal(niceDown(126), 120);
    assert.deepEqual(countRange(10, [30, 70]), [0, 0]);
    assert.equal(fmtCount([0, 0]), "less than 1");
    assert.equal(fmtCount([4, 4]), "4");
  });
  it("never promises more than the typical cost allows, for every model, size and plan", () => {
    const cfg = parseTokenConfig({});
    for (const tier of ["katara", "saka", "all"] as const) {
      const tokens = cfg.plan.tokens[tier];
      for (const e of planEstimates(tokens, ["katara", "saka", "yakko"], cfg.reserve)) {
        const t = cfg.reserve[e.model];
        assert.ok(e.small[1] * t.simple[0] <= tokens && e.small[0] <= e.small[1], `${tier}/${e.model} small`);
        assert.ok(e.typical[1] * t.standard[0] <= tokens, `${tier}/${e.model} typical`);
        assert.ok(e.edits[1] * t.simple[0] * CHANGE_COST_FACTOR <= tokens + 1e-9, `${tier}/${e.model} edits`);
        assert.ok(e.edits[1] >= e.small[1], "an edit is never dearer than a small mod");
        assert.ok(e.typical[1] <= e.small[1], "a typical mod is never cheaper than a small one");
      }
    }
  });
  it("follows the admin cost table instead of hardcoded numbers", () => {
    const cheap = parseTokenConfig({ cyrus_tok_reserve_table: JSON.stringify({ ...DEFAULT_RESERVE_TABLE, katara: { simple: [10, 20], standard: [20, 40], complex: [40, 80] } }) });
    assert.deepEqual(planModelEstimate(750, "katara", cheap.reserve).small, [35, 75]);
    assert.deepEqual(planModelEstimate(750, "katara", parseTokenConfig({}).reserve).small, [10, 25]);
  });
  it("lists the plan's models best first and words it plainly", () => {
    const rows = planEstimates(3500, ["katara", "saka"], DEFAULT_RESERVE_TABLE);
    assert.deepEqual(rows.map((r) => r.model), ["saka", "katara"]);
    assert.match(planEstimateLine(rows[1], "Katara"), /^about \\d+ to \\d+ small mods or \\d+ to \\d+ edits on Katara$/);
    assert.match(readFileSync("components/cyrus-tokens/TokensModal.tsx", "utf8"), /Estimate, depends on size/);
  });
});

describe("cyrus v6 add game: only games Cyrus supports", () => {
  it("nothing is addable while every supported game is on the ring (the dashed branch hides)", () => {
    assert.equal(canAddGame(GAMES), false);
    const c = ringCandidates(GAMES);
    assert.ok(c.every((x) => !x.preset), "registry-only games have no generator");
    assert.deepEqual(c.map((x) => x.id).sort(), CYRUS_GAMES.filter((g) => !GAMES.some((r) => r.id === g.id)).map((g) => g.id).sort());
    assert.ok(c.every((x) => candidateStatus(x) === "Coming soon"));
  });
  it("a supported game off the ring is addable, with its status", () => {
    const ring = GAMES.filter((g) => g.id !== "valheim");
    assert.equal(canAddGame(ring), true);
    const v = ringCandidates(ring)[0];
    assert.equal(v.id, "valheim");
    assert.equal(candidateStatus(v), "Template preview");
    assert.equal(canAddGame(ring, undefined, undefined, ring.length), false, "a full ring adds nothing");
  });
  it("there is no free-text custom game form any more", () => {
    const src = readFileSync("components/cyrus/chrome/AddGameDialog.tsx", "utf8");
    assert.doesNotMatch(src, /<input/);
    assert.match(src, /ringCandidates\\(/);
  });
});

describe("cyrus v6 explain", () => {
  it("failure explanations and retry rules (from v4b)", () => {
