    const warn = safetySummary({ result: { summary: null, commands: [], permissions: [], config: [], warnings: [], files: [], events: [], repairs: 0, queuePosition: 0, safety: { verdict: "warn", findings: [{ severity: "warn", rule: "r", where: "w", message: "reads player files", evidence: "" }, { severity: "warn", rule: "r", where: "w2", message: "reads player files", evidence: "" }] } } });
    assert.deepEqual([warn.verdict, warn.label, warn.notes], ["warn", "Passed with notes", ["reads player files"]]);
  });
  it("a retry of a change asks the change again; a fresh retry starts over", () => {
    assert.deepEqual(retryRequest({ prompt: "A shop", changeRequest: "add /baltop", baseBuildId: "b1", mcVersion: "1.21.4" }), { text: "add /baltop", change: true, mcVersion: "1.21.4" });
    assert.deepEqual(retryRequest({ prompt: "A shop", changeRequest: null, baseBuildId: null, mcVersion: "1.21.11" }), { text: "A shop", change: false, mcVersion: "1.21.11" });
  });
  it("template previews are explained from their own files and labelled", () => {
    assert.match(fileRole("42/media/sandbox-options.txt"), /Settings/);
    assert.match(fileRole("42/mod.info"), /loader reads/);
    assert.match(fileRole("media/lua/client/FooClient.lua"), /Client-side/);
    const e = templateExplain({ name: "Horde Night", summary: "Sirens every seventh night.", tags: ["horde"] }, { name: "Project Zomboid", toolchain: "Lua · Build 42" }, [{ path: "media/lua/server/HordeServer.lua" }, { path: "media/lua/client/HordeClient.lua" }, { path: "README.md" }]);
    assert.equal(e.lead, "Sirens every seventh night.");
    assert.ok(e.points.some((p) => /client part/.test(p)));
    assert.match(e.note, /not been compiled, installed or tested/);
    const tab = readFileSync("components/cyrus/preview/ExplainTab.tsx", "utf8");
    assert.match(tab, /Template preview/);
    assert.match(readFileSync("components/cyrus/preview/PreviewPanel.tsx", "utf8"), /id: "explain", label: "Explain"/);
  });
});

