// THROWAWAY Playwright run ON node-2 (devhost run) for the Cyrus v6 studio-ui work. Never committed.
// BASE=http://127.0.0.1:<port> OUT=dir ONLY=a,b  (adapted from the v5 harness shots.mjs)
import { chromium } from "playwright";
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";

const BASE = process.env.BASE;
const OUT = process.env.OUT || ".cyrus-verify/shots6";
const ONLY = (process.env.ONLY || "").split(",").filter(Boolean);
const want = (k) => !ONLY.length || ONLY.includes(k);
const { token } = JSON.parse(readFileSync(".next.cyrus-session.json", "utf8"));
mkdirSync(OUT, { recursive: true });
const log = [];
const note = (...a) => { const l = a.join(" "); log.push(l); console.log(l); };

const browser = await chromium.launch({ args: ["--disable-dev-shm-usage", "--use-gl=angle", "--use-angle=swiftshader", "--enable-unsafe-swiftshader"] });
async function ctx(w, theme, dsf = 1) {
  const mobile = w < 600;
  const c = await browser.newContext({ viewport: { width: w, height: mobile ? 844 : 900 }, deviceScaleFactor: dsf, isMobile: mobile, hasTouch: mobile });
  const host = new URL(BASE).hostname;
  await c.addCookies([{ name: "nxeon_session", value: token, domain: host, path: "/" }, { name: "nxeon_authed", value: "1", domain: host, path: "/" }]);
  await c.addInitScript((t) => {
    try {
      localStorage.setItem("nx-theme", t);
      for (const k of ["nx-whatsnew-seen", "nx-tour-done", "heard-about-us-dismissed", "promo-trial-dismissed"]) localStorage.setItem(k, "1");
    } catch {}
  }, theme);
  return c;
}
async function go(page, url) {
  for (let i = 0; i < 8; i++) {
    try {
      const r = await page.goto(BASE + url, { waitUntil: "domcontentloaded", timeout: 240000 });
      note("GET", url, r?.status());
      return r;
    } catch (e) {
      if (i === 7) throw e;
      await page.waitForTimeout(8000);
    }
  }
}
async function closePopups(page) {
  for (const name of ["Got it", "Close", "Not now", "Skip", "Dismiss"]) {
    const b = page.getByRole("button", { name, exact: true });
    if ((await b.count()) && (await b.first().isVisible().catch(() => false))) await b.first().click().catch(() => {});
  }
}
const shot = async (page, name, opts = {}) => {
  await page.waitForTimeout(opts.wait ?? 900);
  await page.screenshot({ path: `${OUT}/${name}.png`, fullPage: !!opts.full, timeout: 180000, ...(opts.clip ? { clip: opts.clip } : {}) });
  note("shot", name);
};
const studioReady = async (p) => {
  await p.waitForSelector(".cyrus-root .stage", { timeout: 240000 });
  await p.waitForTimeout(9000);
  await closePopups(p);
};
const esc = async (p, n = 1) => { for (let i = 0; i < n; i++) { await p.keyboard.press("Escape"); await p.waitForTimeout(250); } };
const openMod = async (p, name) => {
  await p.keyboard.press("Control+k");
  await p.waitForTimeout(500);
  await p.keyboard.type(name);
  await p.waitForTimeout(300);
  await p.keyboard.press("Enter");
  await p.waitForTimeout(1500);
};
const tab = async (p, name) => { await p.getByRole("tab", { name: new RegExp(name) }).first().click().catch((e) => note("tab miss", name, e.message.split("\n")[0])); await p.waitForTimeout(900); };

// gallery route is gone
if (want("cores")) {
  const c = await ctx(1440, "dark");
  const p = await c.newPage();
  const r = await go(p, "/dashboard/cyrus/cores");
  note("cores route status", r?.status());
  await c.close();
}

for (const [theme, w] of [["dark", 1440], ["light", 1440], ["dark", 390], ["light", 390]]) {
  const tag = `${theme}-${w}`;
  const c = await ctx(w, theme);
  const p = await c.newPage();
  p.on("pageerror", (e) => note("PAGEERROR", tag, e.message));
  p.on("console", (m) => { if (m.type() === "error") note("CONSOLE", tag, m.text().slice(0, 300)); });
  const r = await go(p, "/dashboard/cyrus");
  const html = await r.text();
  note("SSR", tag, html.includes("cyrus-root") ? "has .cyrus-root" : "MISSING .cyrus-root", html.includes("nx-shell-root") ? "+ portal shell" : "NO portal shell", /rel="icon"[^>]*cyrus\/brand\/icon\.svg|cyrus\/brand\/icon\.svg[^>]*rel="icon"/.test(html) ? "+ cyrus favicon" : "no cyrus favicon");
  await studioReady(p);
  note("legend present:", await p.getByText("Hierarchy", { exact: true }).count(), "add-game ghost:", await p.locator(".node.is-ghost").count(), "Add game btn:", await p.getByRole("button", { name: /Add game/ }).count(), "Cores link:", await p.locator('a[href="/dashboard/cyrus/cores"]').count());
  note("horizontal overflow:", await p.evaluate(() => document.documentElement.scrollWidth - document.documentElement.clientWidth));
  if (want("network")) await shot(p, `01-network-${tag}`);

  if (w >= 1000) {
    if (want("models")) {
      await p.locator(".prompt-shell button[aria-haspopup=listbox]").first().click().catch(() => {});
      await shot(p, `02-model-picker-${tag}`, { wait: 700 });
      await esc(p);
    }
    if (want("chip")) {
      await p.locator(".cyt-chip").first().hover().catch(() => {});
      await shot(p, `03-token-chip-tooltip-${tag}`, { wait: 600 });
      await p.mouse.move(700, 450);
    }
    if (want("plans")) {
      await p.locator(".cyt-chip").first().click().catch(() => {});
      await p.waitForSelector(".cyt-modal", { timeout: 30000 }).catch(() => note("token modal missing"));
      await shot(p, `04-plans-estimates-${tag}`, { wait: 1200 });
      await esc(p);
      await p.locator(".cy-modal-back").first().click({ position: { x: 5, y: 5 } }).catch(() => {});
      await p.waitForTimeout(400);
    }
    if (want("palette") && theme === "dark") {
      await p.keyboard.press("Control+k");
      await p.waitForTimeout(500);
      await shot(p, `05-command-palette-${tag}`, { wait: 600 });
      await p.keyboard.type("expand");
      await shot(p, `05b-command-palette-expand-${tag}`, { wait: 500 });
      await esc(p);
    }
    if (want("realmod")) {
      await openMod(p, "Frostbite Blade");
      await p.waitForSelector(".cyrus-root .code", { timeout: 60000 }).catch(() => note("real mod: code never loaded"));
      await shot(p, `06-real-code-${tag}`, { wait: 1500 });
      await tab(p, "Explain");
      await shot(p, `07-real-explain-${tag}`, { wait: 900 });
      await p.locator("aside[aria-label='Preview panel'] .overflow-y-auto").first().evaluate((el) => el.scrollTo(0, 99999)).catch(() => {});
      await shot(p, `07b-real-explain-bottom-${tag}`, { wait: 700 });
      await tab(p, "Versions");
      await shot(p, `08-real-versions-${tag}`);
      await p.getByRole("button", { name: /Compare/ }).first().click().catch((e) => note("compare miss", e.message.split("\n")[0]));
      await p.waitForSelector("text=/file[s]? changed/", { timeout: 30000 }).catch(() => note("compare never loaded"));
      await shot(p, `09-real-compare-${tag}`, { wait: 1200 });
      await p.getByRole("button", { name: /Close compare/ }).click().catch(() => {});
      await tab(p, "Notes");
      await shot(p, `10-real-notes-avatar-${tag}`);
      await tab(p, "Code");
      // expand: shortcut E (focus off inputs)
      await p.locator("aside[aria-label='Preview panel'] h2").first().click().catch(() => {});
      await p.keyboard.press("e");
      await shot(p, `11-expanded-panel-${tag}`, { wait: 1200 });
      note("panel wide attr:", await p.locator("aside[data-wide='true']").count());
      await esc(p);
      await shot(p, `11b-collapsed-after-esc-${tag}`, { wait: 900 });
      note("panel wide after Esc:", await p.locator("aside[data-wide='true']").count(), "panel open:", await p.locator("aside[aria-label='Preview panel']").count());
      await esc(p, 4);
    }
    if (want("failed")) {
      await openMod(p, "Spleef");
      await shot(p, `12-failed-code-${tag}`, { wait: 1200 });
      await tab(p, "Explain");
      await shot(p, `13-failed-explain-${tag}`, { wait: 900 });
      await esc(p, 4);
    }
    if (want("forge-template")) {
      await p.getByRole("button", { name: "Recenter on the core" }).click().catch(() => {});
      await p.waitForTimeout(600);
      const ta = p.locator("textarea.prompt-textarea");
      await ta.click({ force: true }).catch(() => {});
      await ta.fill("A frost axe for Valheim that freezes and slows what it hits, with a config for the freeze time", { force: true });
      await ta.press("Enter");
      await p.waitForSelector("text=/forged/", { timeout: 120000 }).catch(() => note("template forge: no forged toast"));
      await p.waitForTimeout(1500);
      await tab(p, "Explain");
      await shot(p, `14-template-explain-${tag}`, { wait: 1000 });
      await esc(p, 4);
    }
    if (want("forge-real") && theme === "dark") {
      await p.getByRole("button", { name: "Recenter on the core" }).click().catch(() => {});
      await p.waitForTimeout(600);
      const ta = p.locator("textarea.prompt-textarea");
      await ta.click({ force: true });
      await ta.fill("A frost axe for Minecraft that freezes and slows enemies on critical hits, with a config for the freeze time", { force: true });
      await ta.press("Enter");
      await p.waitForTimeout(3500);
      await shot(p, `15-thinking-coin-${tag}`, { wait: 100 });
      await p.waitForTimeout(6000);
      await shot(p, `15b-forging-coin-${tag}`, { wait: 100 });
      await p.waitForSelector("text=/is ready/", { timeout: 120000 }).catch(() => note("real forge: no ready toast"));
      await shot(p, `16-real-forge-done-${tag}`, { wait: 1500 });
      await esc(p, 4);
    }
  } else {
    if (want("mobile")) {
      await openMod(p, "Frostbite Blade");
      await p.waitForSelector(".cyrus-root .code", { timeout: 60000 }).catch(() => note("mobile: code never loaded"));
      await shot(p, `06-real-code-${tag}`, { wait: 1500 });
      await tab(p, "Explain");
      await shot(p, `07-real-explain-${tag}`, { wait: 900 });
      await p.getByRole("button", { name: "Expand panel" }).first().click().catch((e) => note("expand miss", e.message.split("\n")[0]));
      await shot(p, `11-expanded-sheet-${tag}`, { wait: 900 });
      note("overflow (sheet):", await p.evaluate(() => document.documentElement.scrollWidth - document.documentElement.clientWidth));
      await p.getByRole("button", { name: "Collapse panel" }).first().click().catch(() => {});
      await p.getByRole("button", { name: "Close panel" }).first().click().catch(() => {});
      await p.waitForTimeout(500);
      await p.locator(".prompt-shell button[aria-haspopup=listbox]").first().click().catch(() => {});
      await shot(p, `02-model-picker-${tag}`, { wait: 700 });
      await esc(p);
    }
  }
  await c.close();
}

// logos at 2x: branch orbs and the add-game-less ring, cropped
if (want("logos2x")) {
  for (const theme of ["dark", "light"]) {
    const c = await ctx(1440, theme, 2);
    const p = await c.newPage();
    await go(p, "/dashboard/cyrus");
    await studioReady(p);
    const orbs = p.locator(".node .g-orb");
    const n = await orbs.count();
    note("orbs", n);
    for (let i = 0; i < n; i++) {
      const bb = await orbs.nth(i).boundingBox();
      if (bb) await shot(p, `17-orb-${i}-2x-${theme}`, { wait: 50, clip: { x: bb.x - 8, y: bb.y - 8, width: bb.width + 16, height: bb.height + 40 } });
    }
    await c.close();
  }
}

// sidebar highlight on a normal portal page, both themes
if (want("sidebar")) {
  for (const theme of ["dark", "light"]) {
    const c = await ctx(1440, theme);
    const p = await c.newPage();
    await go(p, "/dashboard");
    await p.waitForLoadState("networkidle", { timeout: 120000 }).catch(() => {});
    await closePopups(p);
    const link = p.locator('a[href="/dashboard/cyrus"]').first();
    const bb = await link.boundingBox();
    await shot(p, `18-sidebar-${theme}`, { wait: 1500, clip: bb ? { x: 0, y: Math.max(0, bb.y - 120), width: 300, height: 260 } : undefined });
    await link.hover().catch(() => {});
    if (bb) await shot(p, `18b-sidebar-hover-${theme}`, { wait: 500, clip: { x: 0, y: Math.max(0, bb.y - 60), width: 300, height: 140 } });
    await c.close();
  }
}

writeFileSync(`${OUT}/log.txt`, log.join("\n") + "\n");
await browser.close();

