                </button>
              </div>
            );
          })}
        </div>
        <div className="flex items-center gap-3 border-t border-cy-line px-4 py-2 text-[11px] text-cy-faint">
          <span>
            <span className="cy5-kbd">↑</span> <span className="cy5-kbd">↓</span> navigate
          </span>
          <span>
            <span className="cy5-kbd">Enter</span> jump
          </span>
          <span className="ml-auto">Camera flies to whatever you pick</span>
        </div>
      </div>
    </div>
  );
}

