  return !!g.real || registry.find((r) => r.id === g.id)?.status === "live";
}

/** The honest empty state of a game branch with no mods (owner, 2026-10-08). */
export function emptyBranchText(g: Pick<Game, "id" | "real" | "name">, registry?: readonly CyrusGame[]): { title: string; body: string } {
  return gameIsLive(g, registry)
    ? { title: `Create your first ${g.name} mod`, body: "Describe it in the prompt below and Cyrus builds it." }
    : { title: "No mods yet", body: `${g.name} support is coming soon. You can still forge a template preview to see how a mod would look.` };
}
